        match outcome {
            Ok(mut value) => {
                self.index_trusted_tool_output(name, &arguments, &mut value);
                Response::result(id, tool_content(&value, false))
            }
            Err(message) => Response::result(
                id,
                tool_content(&json!({ "ok": false, "error": message }), true),
            ),
        }
