    fn runtime_execution_simulate(&self, arguments: &Value) -> Result<Value, String> {
        let run = bioprism_ids::RunId::parse(
            arguments
                .get("run")
                .and_then(Value::as_str)
                .unwrap_or("mcp-runtime-run"),
        )
        .map_err(|error| format!("invalid run id: {error}"))?;
        let policy: EffectPolicy = serde_json::from_value(
            arguments
                .get("policy")
                .cloned()
                .ok_or("policy is required and must be a serialized runtime EffectPolicy")?,
        )
        .map_err(|error| format!("invalid effect policy: {error}"))?;
        let raw_requests = arguments
            .get("requests")
            .cloned()
            .ok_or("requests is required and must be an array of EffectRequest values")?;
        let request_values = raw_requests
            .as_array()
            .ok_or("requests must be an array of EffectRequest values")?;
        if request_values.len() > 1_000 {
            return Err("requests exceeds the 1000-effect safety bound".into());
        }
        let request_bytes = serde_json::to_vec(&raw_requests)
            .map_err(|error| format!("cannot measure request envelope: {error}"))?;
        if request_bytes.len() > 2_000_000 {
            return Err("requests exceed the 2000000-byte safety bound".into());
        }
        let requests: Vec<EffectRequest> = request_values
            .iter()
            .cloned()
            .map(|value| {
                serde_json::from_value(value)
                    .map_err(|error| format!("invalid effect request: {error}"))
            })
            .collect::<Result<_, _>>()?;
        let budget_plan: Option<BudgetPlan> = arguments
            .get("budget")
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .map_err(|error| format!("invalid runtime BudgetPlan: {error}"))?;
        let world =
            runtime_world_from_config(arguments.get("world").unwrap_or(&Value::Null), "world")?;
        let mut recording = RecordingHost::new(run.clone(), world, policy.clone());
        if let Some(plan) = &budget_plan {
            recording = recording.with_budget(BudgetController::from_plan(plan));
        }

        let mut live_outcomes = Vec::new();
        let mut execution_error = None;
        for request in &requests {
            match recording.perform(request.clone()) {
                Ok(outcome) => live_outcomes.push(outcome.into_value()),
                Err(error) => {
                    execution_error = Some(error.to_string());
                    break;
                }
            }
        }
        let (tape, world, journal, budget) = recording.into_parts();
        let recorded_requests = tape.entries().len();
        let mut replay_outcomes = Vec::new();
        let mut replay_error = None;
        let mut replay = ReplayHost::new(tape.clone());
        for request in requests.iter().take(recorded_requests) {
            match replay.perform(request.clone()) {
                Ok(outcome) => replay_outcomes.push(outcome.into_value()),
                Err(error) => {
                    replay_error = Some(error.to_string());
                    break;
                }
            }
        }
        let replay_finish = replay.finish();
        if let Err(error) = &replay_finish {
            replay_error = Some(error.to_string());
        }
        let replay_match = replay_error.is_none() && live_outcomes == replay_outcomes;
        let budget_view = budget.as_ref().map(|controller| {
            json!({
                "accounting": controller.accounting(),
                "warnings": controller.warnings(),
                "aborted_on": controller.aborted_on(),
                "fully_consumed_effects": controller.used(RuntimeResource::ToolCalls)
            })
        });

        let fork = match arguments.get("fork") {
            None | Some(Value::Null) => Value::Null,
            Some(raw_fork) => {
                let fork = raw_fork.as_object().ok_or("fork must be an object")?;
                let step = fork
                    .get("step")
                    .and_then(Value::as_u64)
                    .ok_or("fork.step is required and must be a non-negative integer")?;
                let child_run = bioprism_ids::RunId::parse(
                    fork.get("run")
                        .and_then(Value::as_str)
                        .unwrap_or("mcp-runtime-child"),
                )
                .map_err(|error| format!("invalid fork run id: {error}"))?;
                let raw_suffix = fork.get("requests").cloned().unwrap_or_else(|| json!([]));
                let suffix_values = raw_suffix
                    .as_array()
                    .ok_or("fork.requests must be an array")?;
                if suffix_values.len() > 1_000 {
                    return Err("fork.requests exceeds the 1000-effect safety bound".into());
                }
                let suffix: Vec<EffectRequest> = suffix_values
                    .iter()
                    .cloned()
                    .map(|value| {
                        serde_json::from_value(value)
                            .map_err(|error| format!("invalid fork effect request: {error}"))
                    })
                    .collect::<Result<_, _>>()?;
                if step > tape.len() {
                    json!({
                        "ok": false,
                        "stage": "fork",
                        "step": step,
                        "refusal": format!("fork step {step} is beyond tape length {}", tape.len()),
                        "fail_closed": true
                    })
                } else {
                    let observed = observable_state(&tape, step).map_err(|error| {
                        format!("cannot materialize observed fork state: {error}")
                    })?;
                    let fork_world = runtime_world_from_config(
                        fork.get("world").unwrap_or(&Value::Null),
                        "fork.world",
                    )?;
                    let mut suffix_host =
                        open_suffix(&tape, step, child_run, fork_world, policy.clone())
                            .map_err(|error| format!("cannot open fork suffix: {error}"))?;
                    suffix_host.resume_at_fork();
                    let mut suffix_outcomes = Vec::new();
                    let mut suffix_error = None;
                    for request in &suffix {
                        match suffix_host.perform(request.clone()) {
                            Ok(outcome) => suffix_outcomes.push(outcome.into_value()),
                            Err(error) => {
                                suffix_error = Some(error.to_string());
                                break;
                            }
                        }
                    }
                    let child_tape = suffix_host
                        .finish()
                        .map_err(|error| format!("cannot finish fork suffix: {error}"))?;
                    let comparison = compare_suffixes(&tape, &child_tape);
                    json!({
                        "ok": suffix_error.is_none(),
                        "step": step,
                        "inherited_steps": child_tape.inherited_steps(),
                        "observed_state": observed,
                        "suffix_outcomes": suffix_outcomes,
                        "suffix_error": suffix_error,
                        "child_tape": child_tape,
                        "comparison": comparison,
                        "guarantee": "the inherited prefix is read from the parent tape and is never re-performed by the fork host"
                    })
                }
            }
        };

        let replay_complete = replay_error.is_none() && replay_outcomes.len() == recorded_requests;
        let recording_complete = execution_error.is_none() && recorded_requests == requests.len();
        let fork_requested = !fork.is_null();
        let live_outcome_count = live_outcomes.len();
        let policy_journal_count = journal.len();
        let replay_outcome_count = replay_outcomes.len();

        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/runtime-execution-simulate/0.1",
            "run": run,
            "request_count": requests.len(),
            "recorded_requests": recorded_requests,
            "recording_complete": recording_complete,
            "partial_recording": !recording_complete,
            "live_outcomes": live_outcomes,
            "live_outcome_count": live_outcome_count,
            "execution_error": execution_error,
            "tape": tape,
            "world": {
                "calls": world.calls(),
                "task_millis": world.task_millis(),
                "state_manifest": world.state_manifest(),
                "file_changes": world.journal()
            },
            "policy_journal": journal,
            "policy_journal_count": policy_journal_count,
            "budget": budget_view,
            "replay": {
                "verified": replay_error.is_none(),
                "matched": replay_match,
                "outcomes": replay_outcomes,
                "outcome_count": replay_outcome_count,
                "complete": replay_complete,
                "error": replay_error
            },
            "replay_outcome_count": replay_outcome_count,
            "replay_complete": replay_complete,
            "fork": fork,
            "fork_requested": fork_requested,
            "guarantees": [
                "the supplied effect program runs only against the deterministic in-process world; no host filesystem, network, process, model, message, or payment endpoint is touched",
                "every authorized effect is hash-chained with request, outcome, and performed-versus-simulated provenance",
                "replay checks request identity and consumes the complete recorded prefix, so changed or truncated programs fail closed",
                "budgets charge before an effect and report soft warnings separately from hard exhaustion",
                "forks expose an observable state and inherit the prefix without re-performing it"
            ],
            "limitations": [
                "the in-process world is not a container, subprocess, durable queue, or real provider",
                "a fork starts its suffix source from the caller-supplied fork.world configuration; restoration of external state is not implied",
                "this endpoint audits a bounded request trace and does not infer agent intent or biological validity"
            ]
        }))
    }

    fn onco_boundary_check(&self, arguments: &Value) -> Result<Value, String> {
        let boundary: ResearchBoundary = arguments
            .get("boundary")
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .map_err(|error| format!("invalid research boundary: {error}"))?
            .unwrap_or_else(ResearchBoundary::research_only);
        let request: BoundaryRequest = serde_json::from_value(
            arguments
                .get("request")
                .cloned()
                .ok_or("request is required and must be a serialized BoundaryRequest")?,
        )
        .map_err(|error| format!("invalid boundary request: {error}"))?;
        if request.requested_uses.len() > 100 {
            return Err("boundary request exceeds the 100-use safety bound".into());
        }

        let disposition = match boundary.triage(&request) {
            Ok(disposition) => disposition,
            Err(error) => {
                return Ok(json!({
                    "ok": false,
                    "schema": "bioprism-mcp/onco-boundary-check/0.1",
                    "outcome_kind": "refused",
                    "refusal_kind": "identifiers_present",
                    "stage": "research_boundary",
                    "refusal": error.to_string(),
                    "fail_closed": true,
                    "requested_use_count": request.requested_uses.len(),
                    "identifier_fields_present": true,
                    "guarantee": "direct identifier presence is refused before the request is echoed or analysed"
                }))
            }
        };
        let disposition_value =
            serde_json::to_value(&disposition).map_err(|error| error.to_string())?;
        let disposition_kind = disposition_value["disposition"]
            .as_str()
            .ok_or("boundary disposition must carry a tagged disposition")?;
        let escalation = disposition.escalation();
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/onco-boundary-check/0.1",
            "outcome_kind": "disposition",
            "disposition_kind": disposition_kind,
            "permitted": boundary.permitted(),
            "disposition": disposition,
            "released": disposition.released(),
            "refused": disposition.refused(),
            "terminal_action": disposition.terminal_action(),
            "escalation": escalation,
            "escalation_present": escalation.is_some(),
            "escalation_trigger": escalation.map(|notice| notice.trigger()),
            "escalation_route": escalation.map(|notice| notice.route()),
            "requested_use_count": disposition.released().len() + disposition.refused().len(),
            "released_count": disposition.released().len(),
            "refused_count": disposition.refused().len(),
            "identifier_fields_present": false,
            "research_statement": "Research use only. Not for use in the diagnosis, prognosis, treatment, or triage of any individual.",
            "guarantees": [
                "research uses and individualized clinical uses are split rather than collapsed into a total refusal",
                "claimed role, urgency, and context do not override the fixed research boundary",
                "partial release preserves safe aggregate work while routing refused individual use to a human process"
            ],
            "limitations": [
                "the boundary checks declared uses and identifier fields; it does not inspect embedded instructions in arbitrary source text",
                "a boundary disposition is not clinical advice and does not execute escalation"
            ]
        }))
    }

    fn onco_response_assess(&self, arguments: &Value) -> Result<Value, String> {
        let criterion: ResponseCriterion = serde_json::from_value(
            arguments
                .get("criterion")
                .cloned()
                .ok_or("criterion is required and must be a serialized ResponseCriterion")?,
        )
        .map_err(|error| format!("invalid response criterion: {error}"))?;
        let baseline: ImagingObservation = serde_json::from_value(
            arguments
                .get("baseline")
                .cloned()
                .ok_or("baseline is required and must be an ImagingObservation")?,
        )
        .map_err(|error| format!("invalid baseline imaging observation: {error}"))?;
        let current: ImagingObservation = serde_json::from_value(
            arguments
                .get("current")
                .cloned()
                .ok_or("current is required and must be an ImagingObservation")?,
        )
        .map_err(|error| format!("invalid current imaging observation: {error}"))?;
        let current_acquired: AcquisitionTime = serde_json::from_value(
            arguments
                .get("current_acquired")
                .cloned()
                .ok_or("current_acquired is required and must be an RFC-3339 timestamp")?,
        )
        .map_err(|error| format!("invalid current_acquired timestamp: {error}"))?;
        let baseline_clinical: ClinicalObservation = serde_json::from_value(
            arguments
                .get("baseline_clinical")
                .cloned()
                .ok_or("baseline_clinical is required and must be a ClinicalObservation")?,
        )
        .map_err(|error| format!("invalid baseline clinical observation: {error}"))?;
        let current_clinical: ClinicalObservation = serde_json::from_value(
            arguments
                .get("current_clinical")
                .cloned()
                .ok_or("current_clinical is required and must be a ClinicalObservation")?,
        )
        .map_err(|error| format!("invalid current clinical observation: {error}"))?;
        let treatment: TreatmentContext = serde_json::from_value(
            arguments
                .get("treatment")
                .cloned()
                .ok_or("treatment is required and must be a TreatmentContext")?,
        )
        .map_err(|error| format!("invalid treatment context: {error}"))?;
        let evidence: ProgressionEvidence = arguments
            .get("evidence")
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .map_err(|error| format!("invalid progression evidence: {error}"))?
            .unwrap_or_default();
        let nadir_spd_mm2 = match arguments.get("nadir_spd_mm2") {
            None | Some(Value::Null) => None,
            Some(value) => Some(
                value
                    .as_f64()
                    .ok_or("nadir_spd_mm2 must be a finite number or null")?,
            ),
        };
        let measurement_error_fraction = arguments
            .get("measurement_error_fraction")
            .and_then(Value::as_f64)
            .unwrap_or(0.0);

        let request = ResponseRequest {
            criterion: &criterion,
            baseline: &baseline,
            current: &current,
            current_acquired,
            nadir_spd_mm2,
            baseline_clinical: &baseline_clinical,
            current_clinical: &current_clinical,
            treatment: &treatment,
            evidence: &evidence,
            measurement_error_fraction,
        };
        let assessment = match onco_assess(&request) {
            Ok(assessment) => assessment,
            Err(error) => {
                return Ok(json!({
                    "ok": false,
                    "schema": "bioprism-mcp/onco-response-assess/0.1",
                    "outcome_kind": "refused",
                    "refusal_kind": "assessment_error",
                    "stage": "response_assessment",
                    "refusal": error.to_string(),
                    "fail_closed": true,
                    "criterion": criterion,
                    "treatment": treatment,
                    "evidence_present": arguments.get("evidence").is_some(),
                    "guarantee": "invalid or unsupported measurements never become stable, response, or progression calls"
                }))
            }
        };
        let assessment_value =
            serde_json::to_value(&assessment).map_err(|error| error.to_string())?;
        let call_kind = assessment_value["call"]["call"]
            .as_str()
            .ok_or("response assessment must carry a tagged call")?;
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/onco-response-assess/0.1",
            "outcome_kind": "assessment",
            "call_kind": call_kind,
            "unconfirmed_reading": assessment.unconfirmed_reading,
            "criterion": criterion,
            "treatment": treatment,
            "criterion_recognises_post_treatment_change": criterion.recognises_post_treatment_change,
            "post_treatment_window_days": treatment.modality.post_treatment_window_days(),
            "pseudoresponse_possible": treatment.modality.causes_pseudoresponse(),
            "measurement_error_fraction": measurement_error_fraction,
            "evidence_present": arguments.get("evidence").is_some(),
            "criterion_divergence_present": assessment.divergence_from_criterion.is_some(),
            "sensitivity_flips": assessment.sensitivity.flips_within_measurement_error,
            "hypothesis_non_identifiable": assessment.hypotheses.is_non_identifiable(),
            "assessment": assessment,
            "call_label": assessment.call.label(),
            "withheld_progression": assessment.withheld_progression(),
            "hypothesis_count": assessment.hypotheses.entries().len(),
            "evidence_requests": assessment.hypotheses.evidence_requests(),
            "guarantees": [
                "the unconfirmed radiologic reading is separate from the reportable call",
                "post-treatment change without confirmation remains not evaluable and never becomes stable disease",
                "the surviving differential and discriminating evidence requests remain visible"
            ],
            "limitations": [
                "this is a research-world assessment, not a diagnosis, prognosis, treatment recommendation, or care triage",
                "advanced imaging and calibrated probabilities are not inferred when they are absent from the request"
            ]
        }))
    }

    fn onco_worldline_view(&self, arguments: &Value) -> Result<Value, String> {
        let worldline: TumourWorldline = serde_json::from_value(
            arguments
                .get("worldline")
                .cloned()
                .ok_or("worldline is required and must be a serialized TumourWorldline")?,
        )
        .map_err(|error| format!("invalid tumour worldline: {error}"))?;
        if worldline.timepoints().len() > 100_000 {
            return Err("tumour worldline exceeds the 100000-timepoint safety bound".into());
        }

        let cutoff = match arguments.get("visible_at") {
            None | Some(Value::Null) => None,
            Some(value) => {
                let text = value
                    .as_str()
                    .ok_or("visible_at must be an RFC-3339 string or null")?;
                let timestamp = bioprism_scope::Timestamp::parse(text)
                    .map_err(|error| format!("invalid visible_at timestamp: {error}"))?;
                Some(AvailabilityTime::new(timestamp))
            }
        };
        let biological_order: Vec<&str> = worldline
            .timepoints()
            .iter()
            .map(Timepoint::label)
            .collect();
        let record_order: Vec<&str> = worldline
            .in_record_order()
            .into_iter()
            .map(Timepoint::label)
            .collect();
        let visible = cutoff.map(|at| worldline.visible_at(at));
        let visible_labels = visible.as_ref().map(|timepoints| {
            timepoints
                .iter()
                .map(|timepoint| timepoint.label())
                .collect::<Vec<_>>()
        });
        let hidden_labels = cutoff.map(|at| {
            worldline
                .timepoints()
                .iter()
                .filter(|timepoint| timepoint.visible() > at)
                .map(Timepoint::label)
                .collect::<Vec<_>>()
        });
        let record_index = |label: &str| {
            record_order
                .iter()
                .position(|record_label| *record_label == label)
                .expect("every biological timepoint must have a record-order position")
        };
        let rows: Vec<Value> = worldline
            .timepoints()
            .iter()
            .enumerate()
            .map(|(biological_index, timepoint)| {
                let clocks = timepoint.clocks();
                let visible_at_cutoff = cutoff.map(|at| clocks.visible <= at);
                let visibility_state = match visible_at_cutoff {
                    Some(true) => "visible",
                    Some(false) => "hidden_from_agent",
                    None => "not_filtered",
                };
                json!({
                    "label": timepoint.label(),
                    "biological_index": biological_index,
                    "record_index": record_index(timepoint.label()),
                    "clocks": clocks,
                    "acquired": clocks.acquired,
                    "recorded": clocks.recorded,
                    "released": clocks.released,
                    "visible": clocks.visible,
                    "days_from_baseline": worldline.time_from_baseline(timepoint).days(),
                    "observation": timepoint.observation(),
                    "visibility_state": visibility_state,
                    "visible_at_cutoff": visible_at_cutoff,
                })
            })
            .collect();

        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/onco-worldline-view/0.1",
            "subject": worldline.subject().as_str(),
            "baseline": worldline.baseline().label(),
            "timepoint_count": worldline.timepoints().len(),
            "biological_order": biological_order,
            "record_order": record_order,
            "record_order_differs": biological_order != record_order,
            "clock_axes": ["acquired", "recorded", "released", "visible"],
            "clock_order_guaranteed": true,
            "baseline_biological_index": worldline
                .timepoints()
                .iter()
                .position(|timepoint| timepoint.label() == worldline.baseline().label())
                .expect("the worldline baseline must be present"),
            "baseline_record_index": record_index(worldline.baseline().label()),
            "visibility_cutoff": cutoff.map(|at| at.timestamp().to_rfc3339()),
            "visibility_filter_applied": cutoff.is_some(),
            "visible_timepoints": visible_labels,
            "hidden_from_agent": hidden_labels,
            "visibility_partition": {
                "cutoff": cutoff.map(|at| at.timestamp().to_rfc3339()),
                "filter_applied": cutoff.is_some(),
                "visible": visible.as_ref().map(|timepoints| timepoints.iter().map(|timepoint| timepoint.label()).collect::<Vec<_>>()),
                "hidden": cutoff.map(|at| worldline.timepoints().iter().filter(|timepoint| timepoint.visible() > at).map(Timepoint::label).collect::<Vec<_>>()),
                "visible_count": visible.as_ref().map(Vec::len),
                "hidden_count": hidden_labels.as_ref().map(Vec::len),
            },
            "visible_count": visible.as_ref().map(Vec::len),
            "hidden_count": hidden_labels.as_ref().map(Vec::len),
            "timepoints": rows,
            "guarantees": [
                "biological order is acquisition order and is reported separately from record order",
                "visibility is cut on agent-visibility time rather than acquisition time",
                "the baseline-relative day count uses only the acquisition clock",
                "hidden future evidence remains distinguishable from absent or unrecorded evidence"
            ],
            "limitations": [
                "the tool audits and renders a supplied worldline; it does not infer missing observations or repair clocks",
                "the worldline contains exact timestamps and does not model date uncertainty, treatment interruptions, or specimen lineage"
            ]
        }))
    }

    fn onco_classification_check(&self, arguments: &Value) -> Result<Value, String> {
        let histology: Histology = serde_json::from_value(
            arguments
                .get("histology")
                .cloned()
                .ok_or("histology is required and must be a serialized Histology")?,
        )
        .map_err(|error| format!("invalid histology: {error}"))?;
        let panel: MarkerPanel = serde_json::from_value(
            arguments
                .get("panel")
                .cloned()
                .ok_or("panel is required and must be a serialized MarkerPanel")?,
        )
        .map_err(|error| format!("invalid molecular marker panel: {error}"))?;
        let states: Vec<Value> = panel
            .iter()
            .map(|(marker, state)| json!({ "marker": marker, "state": state }))
            .collect();
        if states.len() > 100 {
            return Err("molecular marker panel exceeds the 100-marker safety bound".into());
        }
        let resolution = onco_classify(histology, &panel);
        let resolution_value =
            serde_json::to_value(&resolution).map_err(|error| error.to_string())?;
        let resolution_kind = resolution_value
            .get("resolution")
            .and_then(Value::as_str)
            .ok_or("classification resolution must carry a tagged resolution kind")?;
        let obligation_count = resolution.obligations().len();
        let observed_panel_state_count = panel
            .iter()
            .filter(|(_, state)| state.is_observed())
            .count();
        let unobserved_panel_state_count = states.len().saturating_sub(observed_panel_state_count);
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/onco-classification-check/0.1",
            "histology": histology,
            "resolution": resolution_value,
            "resolution_kind": resolution_kind,
            "is_integrated": resolution.is_integrated(),
            "entity": resolution.entity(),
            "obligations": resolution.obligations(),
            "obligation_count": obligation_count,
            "panel_states": states,
            "panel_state_count": states.len(),
            "observed_panel_state_count": observed_panel_state_count,
            "unobserved_panel_state_count": unobserved_panel_state_count,
            "guarantees": [
                "histology selects candidates but never supplies a molecular call",
                "unobserved assays remain obligations and are never treated as negative",
                "mixed, unresolved, provisional, and not-otherwise-resolved states remain distinct",
                "an entity is returned only for an integrated resolution"
            ],
            "limitations": [
                "the criteria table is the deliberately bounded worked instantiation shipped by bioprism-onco",
                "methylation, fusion, purity, and lower-grade histologic evidence are not inferred"
            ]
        }))
    }

    fn oncoworlds_identity_join(&self, arguments: &Value) -> Result<Value, String> {
        let left: Artifact = serde_json::from_value(
            arguments
                .get("left")
                .cloned()
                .ok_or("left is required and must be a serialized onco-worlds Artifact")?,
        )
        .map_err(|error| format!("invalid left artifact: {error}"))?;
        let right: Artifact = serde_json::from_value(
            arguments
                .get("right")
                .cloned()
                .ok_or("right is required and must be a serialized onco-worlds Artifact")?,
        )
        .map_err(|error| format!("invalid right artifact: {error}"))?;
        let unit: AnalysisUnit = serde_json::from_value(arguments.get("unit").cloned().ok_or(
            "unit is required and must be participant, lesion, specimen, or imaging_series",
        )?)
        .map_err(|error| format!("invalid analysis unit: {error}"))?;
        let evidence: IdentityEvidence = arguments
            .get("evidence")
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .map_err(|error| format!("invalid identity evidence: {error}"))?
            .unwrap_or_else(IdentityEvidence::new);
        if evidence.links().len() > 1_000 {
            return Err("identity evidence exceeds the 1000-link safety bound".into());
        }
        let bridge: Option<EpochBridge> = arguments
            .get("epoch_bridge")
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .map_err(|error| format!("invalid epoch bridge: {error}"))?;
        let verdict = match bridge.as_ref() {
            Some(bridge) => joinable_with_bridge(&left, &right, unit, &evidence, Some(bridge)),
            None => joinable_with_bridge(&left, &right, unit, &evidence, None),
        };
        let verdict = match verdict {
            Ok(()) => JoinVerdict::Joinable,
            Err(reason) => JoinVerdict::Declined { reason },
        };
        let report = JoinReport {
            left: left.label.clone(),
            right: right.label.clone(),
            unit,
            verdict,
        };
        let report_value = serde_json::to_value(&report).map_err(|error| error.to_string())?;
        let verdict_kind = report_value["verdict"]["verdict"]
            .as_str()
            .ok_or("identity join report must carry a tagged verdict")?;
        let refusal_kind = report_value["verdict"]["reason"]["refusal"]
            .as_str()
            .map(str::to_owned);
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/oncoworlds-identity-join/0.1",
            "joinable": report.verdict.is_joinable(),
            "report": report,
            "verdict_kind": verdict_kind,
            "refusal_kind": refusal_kind,
            "bridge_declared": bridge.is_some(),
            "epoch_bridge": bridge,
            "identity_evidence_present": !evidence.links().is_empty(),
            "identity_link_count": evidence.links().len(),
            "bridge_warrant_present": bridge.as_ref().is_some_and(|item| !item.warrant.is_empty()),
            "checked_dimensions": [
                "participant_identity",
                "identifier_width",
                "identity_evidence",
                "relation_licence",
                "permissible_use",
                "lesion_identity",
                "disease_epoch",
                "specimen_identity"
            ],
            "guarantees": [
                "participant identity is checked before local specimen or lesion identifiers",
                "truncated identifiers, unlicensed relations, missing permissible use, epoch mismatch, and specimen mismatch are typed refusals",
                "a declined join is returned as an auditable result rather than discarded",
                "an epoch bridge is accepted only when it names both epochs and carries a caller-supplied warrant"
            ],
            "limitations": [
                "the tool consumes caller-supplied identity evidence and does not run fingerprint, sex-chromosome, or contamination oracles",
                "a declared bridge is a warrant for review, not proof that the disease epochs are biologically interchangeable"
            ]
        }))
    }

    fn onco_outcome_analyze(&self, arguments: &Value) -> Result<Value, String> {
        let follow_up: FollowUp = serde_json::from_value(
            arguments
                .get("follow_up")
                .cloned()
                .ok_or("follow_up is required and must be a serialized FollowUp")?,
        )
        .map_err(|error| format!("invalid oncology follow-up: {error}"))?;
        let estimand: Estimand = serde_json::from_value(
            arguments
                .get("estimand")
                .cloned()
                .ok_or("estimand is required and must be declared before analysis")?,
        )
        .map_err(|error| format!("invalid oncology estimand: {error}"))?;
        let analysis = follow_up.analyse(&estimand);
        let at_risk_days = analysis.at_risk_days;
        let immortal_time_days = analysis.immortal_time_days;
        let event = analysis.outcome.is_event();
        let censoring_reason = analysis.outcome.censoring_reason();
        let informative_bias_flags = analysis
            .bias_flags
            .iter()
            .filter(|bias| {
                matches!(
                    bias,
                    bioprism_onco::AnalysisBias::InformativeLossToFollowUp
                        | bioprism_onco::AnalysisBias::CompetingDeath
                        | bioprism_onco::AnalysisBias::TreatmentSwitching
                )
            })
            .collect::<Vec<_>>();
        let all_bias_flags = analysis.bias_flags.clone();
        let bias_count = all_bias_flags.len();
        let informative_bias_count = informative_bias_flags.len();
        let outcome = analysis.outcome;
        let censoring_informative =
            censoring_reason.map(|reason| reason.is_potentially_informative());
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/onco-outcome-analyze/0.1",
            "analysis": analysis,
            "outcome": outcome,
            "bias_flags": all_bias_flags,
            "bias_count": bias_count,
            "informative_bias_count": informative_bias_count,
            "at_risk_days": at_risk_days,
            "immortal_time_days": immortal_time_days,
            "left_truncated": immortal_time_days > 0,
            "event": event,
            "censoring_reason": censoring_reason,
            "censoring_informative": censoring_informative,
            "informative_bias_flags": informative_bias_flags,
            "guarantees": [
                "the caller must state the estimand before the per-subject outcome is interpreted",
                "loss to follow-up is censoring and never an event",
                "competing death remains distinguishable from ordinary non-informative censoring",
                "delayed risk-set entry reports immortal-time exposure instead of counting it as at-risk time"
            ],
            "limitations": [
                "this produces one-subject analysis records; it does not estimate survival, hazard ratios, or cumulative incidence",
                "cohort-level landmark and follow-up-intensity bias require a cohort audit beyond this record"
            ]
        }))
    }

    fn oncoworlds_model_transport(&self, arguments: &Value) -> Result<Value, String> {
        let result: ModelResult = serde_json::from_value(
            arguments
                .get("result")
                .cloned()
                .ok_or("result is required and must be a serialized ModelResult")?,
        )
        .map_err(|error| format!("invalid model result: {error}"))?;
        let fidelity: FidelityEvidence = arguments
            .get("fidelity")
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .map_err(|error| format!("invalid fidelity evidence: {error}"))?
            .unwrap_or_default();
        let cohort: EstablishmentCohort = serde_json::from_value(
            arguments
                .get("establishment")
                .cloned()
                .ok_or("establishment is required and must be an EstablishmentCohort")?,
        )
        .map_err(|error| format!("invalid establishment cohort: {error}"))?;
        if cohort.attempted > 1_000_000 || cohort.established > 1_000_000 {
            return Err("establishment counts exceed the 1000000-subject safety bound".into());
        }
        let claimed_n = arguments
            .get("claimed_n")
            .and_then(Value::as_u64)
            .ok_or("claimed_n is required and must be a non-negative integer")?;
        if claimed_n > 1_000_000 {
            return Err("claimed_n exceeds the 1000000-subject safety bound".into());
        }
        let transport: DeclaredTransport = serde_json::from_value(
            arguments
                .get("transport")
                .cloned()
                .ok_or("transport is required and must be a serialized DeclaredTransport")?,
        )
        .map_err(|error| format!("invalid declared transport: {error}"))?;

        let fidelity_axes: Vec<Value> = result
            .rests_on
            .iter()
            .map(|axis| {
                json!({
                    "axis": axis,
                    "passage": result.model.passage,
                    "measured": fidelity.covers(*axis, result.model.passage)
                })
            })
            .collect();
        let transport_assumption_names: Vec<String> =
            transport.assumption_names().map(str::to_owned).collect();
        let model_identity = json!({
            "model": result.model.model,
            "system": result.model.system,
            "source_specimen": result.model.source_specimen,
            "passage": result.model.passage,
            "verified_against_source": result.model.verified_against_source
        });
        let replicate_summary = json!({
            "technical_wells": result.replicates.technical_wells,
            "biological_replicates": result.replicates.biological_replicates,
            "effective_biological_n": result.replicates.effective_n(),
            "claimed_n": claimed_n
        });
        let establishment_summary = json!({
            "attempted": cohort.attempted,
            "established": cohort.established,
            "selected": cohort.is_selected(),
            "selection_modelled": cohort.selection_modelled
        });

        match onco_transport_model(&result, &fidelity, cohort, claimed_n as usize, &transport) {
            Ok(claim) => Ok(json!({
                "ok": true,
                "schema": "bioprism-mcp/oncoworlds-model-transport/0.1",
                "supported": true,
                "outcome_kind": "supported",
                "model_statement": result.as_stated(),
                "effect": result.effect,
                "model_identity": model_identity,
                "rests_on": result.rests_on,
                "fidelity_axes": fidelity_axes,
                "establishment": establishment_summary,
                "replicates": replicate_summary,
                "transport_assumption_names": transport_assumption_names,
                "required_assumptions": MODEL_REQUIRED_ASSUMPTIONS,
                "effective_biological_n": result.replicates.effective_n(),
                "patient_relevant_claim": claim,
                "guarantees": [
                    "model identity is checked before any patient-level transport",
                    "fidelity is required at the passage on which the effect was observed",
                    "establishment selection and technical-versus-biological replication remain explicit",
                    "the transport carries a loss ledger and every required assumption"
                ],
                "limitations": [
                    "the tool checks declared transport structure; it does not validate identity, fidelity, or assumptions against an external oracle",
                    "a supported patient-relevant claim is still a research transport, not a clinical treatment recommendation"
                ]
            })),
            Err(refusal) => {
                let refusal_value =
                    serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                Ok(json!({
                    "ok": false,
                    "schema": "bioprism-mcp/oncoworlds-model-transport/0.1",
                    "supported": false,
                    "outcome_kind": "refused",
                    "refusal_kind": refusal_value["refusal"],
                    "stage": "model_to_patient_transport",
                    "refusal": refusal_value,
                    "refusal_text": refusal.to_string(),
                    "fail_closed": true,
                    "model_statement": result.as_stated(),
                    "effect": result.effect,
                    "model_identity": model_identity,
                    "rests_on": result.rests_on,
                    "fidelity_axes": fidelity_axes,
                    "establishment": establishment_summary,
                    "replicates": replicate_summary,
                    "transport_assumption_names": transport_assumption_names,
                    "required_assumptions": MODEL_REQUIRED_ASSUMPTIONS,
                    "guarantee": "a model-system effect is never relabelled as patient evidence when an identity, fidelity, selection, replication, loss, or assumption boundary is missing"
                }))
            }
        }
    }

    fn oncoworlds_methylation_classify(&self, arguments: &Value) -> Result<Value, String> {
        let classifier: ClassifierVersion = serde_json::from_value(
            arguments
                .get("classifier")
                .cloned()
                .ok_or("classifier is required and must be a ClassifierVersion")?,
        )
        .map_err(|error| format!("invalid classifier version: {error}"))?;
        let scores: std::collections::BTreeMap<
            MethylationClass,
            bioprism_oncoworlds::CalibratedScore,
        > = serde_json::from_value(arguments.get("scores").cloned().ok_or(
            "scores is required and must be a map from class labels to calibrated scores",
        )?)
        .map_err(|error| format!("invalid calibrated score map: {error}"))?;
        if scores.len() > 10_000 {
            return Err("methylation score map exceeds the 10000-class safety bound".into());
        }
        let context: SampleContext = serde_json::from_value(
            arguments
                .get("context")
                .cloned()
                .ok_or("context is required and must be a SampleContext")?,
        )
        .map_err(|error| format!("invalid methylation sample context: {error}"))?;
        let classifier_value =
            serde_json::to_value(&classifier).map_err(|error| error.to_string())?;
        let qc_value = serde_json::to_value(&context.qc).map_err(|error| error.to_string())?;
        let tumour_content_value =
            serde_json::to_value(context.tumour_content).map_err(|error| error.to_string())?;
        let score_classes: Vec<String> = scores
            .keys()
            .map(|class| class.as_str().to_owned())
            .collect();
        match onco_classify_methylation(&classifier, &scores, &context) {
            Ok(report) => {
                let classified = report.outcome.is_classified();
                let class = report.outcome.class().cloned();
                let report_value =
                    serde_json::to_value(&report).map_err(|error| error.to_string())?;
                let outcome_kind = report_value["outcome"]["outcome"]
                    .as_str()
                    .ok_or("methylation report must carry a tagged outcome")?;
                Ok(json!({
                    "ok": true,
                    "schema": "bioprism-mcp/oncoworlds-methylation-classify/0.1",
                    "outcome_kind": outcome_kind,
                    "classified": classified,
                    "class": class,
                    "classifier": classifier_value,
                    "classifier_threshold": classifier.reporting_threshold,
                    "threshold_declared": classifier.reporting_threshold.is_some(),
                    "qc": qc_value,
                    "tumour_content": tumour_content_value,
                    "score_count": scores.len(),
                    "score_classes": score_classes,
                    "caveat_count": report.caveats.len(),
                    "nearest_present": report_value["outcome"]["nearest"].is_object(),
                    "report": report,
                    "denominator_policy": "an unclassifiable result remains a result and must stay in the evaluation denominator",
                    "guarantees": [
                        "a classifier must declare its own reporting threshold",
                        "quality-control failure and below-threshold abstention remain distinct outcomes",
                        "nearest class evidence never becomes a class call",
                        "tumour-content absence is retained as a caveat rather than silently imputed"
                    ],
                    "limitations": [
                        "no array preprocessing, batch correction, classifier fitting, or tumour-content threshold is inferred",
                        "the tool evaluates supplied calibrated scores; it does not validate the classifier against a reference cohort"
                    ]
                }))
            }
            Err(refusal) => Ok(json!({
                "ok": false,
                "schema": "bioprism-mcp/oncoworlds-methylation-classify/0.1",
                "outcome_kind": "refused",
                "refusal_kind": serde_json::to_value(&refusal)
                    .map_err(|error| error.to_string())?["refusal"].clone(),
                "stage": "methylation_classification",
                "refusal": serde_json::to_value(&refusal).map_err(|error| error.to_string())?,
                "refusal_text": refusal.to_string(),
                "fail_closed": true,
                "classifier": classifier_value,
                "classifier_threshold": classifier.reporting_threshold,
                "threshold_declared": classifier.reporting_threshold.is_some(),
                "qc": qc_value,
                "tumour_content": tumour_content_value,
                "score_count": scores.len(),
                "score_classes": score_classes,
                "guarantee": "an undeclared threshold or other typed methylation refusal never becomes a maximum-score class call"
            })),
        }
    }

    fn oncoworlds_methylation_compare(&self, arguments: &Value) -> Result<Value, String> {
        let left: VersionedResult = serde_json::from_value(
            arguments
                .get("left")
                .cloned()
                .ok_or("left is required and must be a VersionedResult")?,
        )
        .map_err(|error| format!("invalid left versioned result: {error}"))?;
        let right: VersionedResult = serde_json::from_value(
            arguments
                .get("right")
                .cloned()
                .ok_or("right is required and must be a VersionedResult")?,
        )
        .map_err(|error| format!("invalid right versioned result: {error}"))?;
        let comparison = onco_reconcile_methylation(&left, &right);
        let comparison_value =
            serde_json::to_value(&comparison).map_err(|error| error.to_string())?;
        let left_outcome =
            serde_json::to_value(&left.outcome).map_err(|error| error.to_string())?;
        let right_outcome =
            serde_json::to_value(&right.outcome).map_err(|error| error.to_string())?;
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/oncoworlds-methylation-compare/0.1",
            "divergence_kind": comparison_value["divergence"]["divergence"],
            "classifier_changed": left.classifier != right.classifier,
            "left_outcome_kind": left_outcome["outcome"],
            "right_outcome_kind": right_outcome["outcome"],
            "stable_evidence_count": comparison.stable_evidence.len(),
            "comparison": comparison,
            "left_classifier": left.classifier,
            "right_classifier": right.classifier,
            "guarantees": [
                "classifier-version changes are reported as version-conditioned evidence",
                "the earlier result is not rewritten as wrong merely because a reference updated",
                "two unclassifiable results remain distinct from agreement on a class"
            ],
            "limitations": [
                "no cross-version ontology mapping or stable corroborating evidence is inferred",
                "this compares supplied results and does not rerun either classifier"
            ]
        }))
    }

    fn oncoworlds_radiogenomic_check(&self, arguments: &Value) -> Result<Value, String> {
        let claim: RadiogenomicClaim = serde_json::from_value(
            arguments
                .get("claim")
                .cloned()
                .ok_or("claim is required and must be a RadiogenomicClaim")?,
        )
        .map_err(|error| format!("invalid radiogenomic claim: {error}"))?;
        let design: EvaluationDesign = serde_json::from_value(
            arguments
                .get("design")
                .cloned()
                .ok_or("design is required and must be an EvaluationDesign")?,
        )
        .map_err(|error| format!("invalid radiogenomic evaluation design: {error}"))?;
        let observation: bioprism_oncoworlds::SpecimenObservation = serde_json::from_value(
            arguments
                .get("observation")
                .cloned()
                .ok_or("observation is required and must be a SpecimenObservation")?,
        )
        .map_err(|error| format!("invalid specimen observation: {error}"))?;
        let transport: DeclaredTransport = serde_json::from_value(
            arguments
                .get("transport")
                .cloned()
                .ok_or("transport is required and must be a DeclaredTransport")?,
        )
        .map_err(|error| format!("invalid declared transport: {error}"))?;
        let claim_target = serde_json::to_value(claim.target).map_err(|error| error.to_string())?;
        let claim_statement = claim.statement.clone();
        let design_summary = json!({
            "split_unit": design.split_unit,
            "feature_provenance": design.feature_provenance,
            "feature_version": design.feature_version,
            "external_cohort": design.external_cohort,
            "strata": design.strata,
            "mechanism_strata_present": MECHANISM_STRATA.iter().all(|stratum| design.strata.contains(*stratum))
        });
        let transport_assumption_names: Vec<String> =
            transport.assumption_names().map(str::to_owned).collect();
        match onco_assert_radiogenomic_claim(claim, &design, &observation, &transport) {
            Ok(supported) => Ok(json!({
                "ok": true,
                "schema": "bioprism-mcp/oncoworlds-radiogenomic-check/0.1",
                "supported": true,
                "outcome_kind": "supported",
                "claim_target": claim_target,
                "claim_statement": claim_statement,
                "design": design_summary,
                "transport_assumption_names": transport_assumption_names,
                "required_assumptions": REQUIRED_ASSUMPTIONS,
                "supported_claim": supported,
                "guarantees": [
                    "participant-safe splitting, training-only feature fitting, and pre-specified external cohorts are checked before claim scope",
                    "specimen negative calls do not silently become tumour-level labels",
                    "mechanism claims require the declared site and scanner strata",
                    "cross-scope transport carries losses and required assumptions"
                ],
                "limitations": [
                    "no imaging feature extraction, predictive model, AUROC, or causal effect is computed",
                    "the tool checks design and scope declarations supplied by the caller"
                ]
            })),
            Err(refusal) => Ok(json!({
                "ok": false,
                "schema": "bioprism-mcp/oncoworlds-radiogenomic-check/0.1",
                "supported": false,
                "outcome_kind": "refused",
                "claim_target": claim_target,
                "claim_statement": claim_statement,
                "design": design_summary,
                "transport_assumption_names": transport_assumption_names,
                "required_assumptions": REQUIRED_ASSUMPTIONS,
                "refusal_kind": serde_json::to_value(&refusal)
                    .map_err(|error| error.to_string())?["refusal"].clone(),
                "stage": "radiogenomic_claim",
                "refusal": serde_json::to_value(&refusal).map_err(|error| error.to_string())?,
                "refusal_text": refusal.to_string(),
                "fail_closed": true,
                "guarantee": "a leaky evaluation, specimen-scoped label, unstratified mechanism claim, or undeclared transport never becomes a supported mechanistic statement"
            })),
        }
    }

    fn oncoworlds_clonal_history_check(&self, arguments: &Value) -> Result<Value, String> {
        let population: TumourPopulation = serde_json::from_value(
            arguments
                .get("population")
                .cloned()
                .ok_or("population is required and must be a TumourPopulation")?,
        )
        .map_err(|error| format!("invalid tumour population: {error}"))?;
        let candidates: Vec<ClonalHistory> = serde_json::from_value(
            arguments
                .get("candidates")
                .cloned()
                .ok_or("candidates is required and must be an array of ClonalHistory values")?,
        )
        .map_err(|error| format!("invalid clonal history candidates: {error}"))?;
        if candidates.len() > 10_000 {
            return Err(
                "clonal history candidate set exceeds the 10000-history safety bound".into(),
            );
        }
        let result = onco_compatible_histories(&population, candidates);
        let compatible_count = result.compatible.len();
        let rejected_count = result.rejected.len();
        let unique = match result.sole() {
            Ok(history) => json!({ "ok": true, "history": history }),
            Err(refusal) => json!({
                "ok": false,
                "refusal": serde_json::to_value(&refusal).map_err(|error| error.to_string())?,
                "refusal_text": refusal.to_string()
            }),
        };
        let unique_status = if unique.get("ok").and_then(Value::as_bool) == Some(true) {
            "unique"
        } else if unique["refusal"]["refusal"] == json!("ambiguous") {
            "ambiguous"
        } else {
            "refused"
        };
        let rejected_records: Vec<Value> = result
            .rejected
            .iter()
            .map(|(history, refusal)| {
                let refusal_value =
                    serde_json::to_value(refusal).expect("clonal refusal is serializable");
                let refusal_kind = refusal_value
                    .get("refusal")
                    .and_then(Value::as_str)
                    .unwrap_or("unknown");
                json!({
                    "history": history,
                    "refusal": refusal,
                    "refusal_kind": refusal_kind,
                    "refusal_text": refusal.to_string(),
                })
            })
            .collect();
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/oncoworlds-clonal-history-check/0.1",
            "compatible_count": compatible_count,
            "rejected_count": rejected_count,
            "candidate_count": compatible_count + rejected_count,
            "compatible": result.compatible,
            "rejected": result.rejected,
            "rejected_records": rejected_records,
            "unique_history": unique,
            "unique_status": unique_status,
            "guarantees": [
                "candidate histories are audited against fraction, ancestry, cycle, and whole-tumour constraints",
                "rejected histories remain visible with their typed refusal",
                "multiple compatible histories remain ambiguity rather than being collapsed to the first candidate",
                "the tool checks supplied histories and does not infer a phylogeny from raw variant data"
            ],
            "limitations": [
                "no clonal tree enumeration, sequencing error model, or causal treatment attribution is performed",
                "compatibility is arithmetic consistency, not proof that one history is biologically true"
            ]
        }))
    }

    fn oncoworlds_clonal_evidence_check(&self, arguments: &Value) -> Result<Value, String> {
        let mut checks = serde_json::Map::new();

        if let Some(value) = arguments.get("promotion") {
            let object = value.as_object().ok_or("promotion must be an object")?;
            let observation: SpecimenObservation = serde_json::from_value(
                object
                    .get("observation")
                    .cloned()
                    .ok_or("promotion.observation is required")?,
            )
            .map_err(|error| format!("invalid promotion specimen observation: {error}"))?;
            let observation_value =
                serde_json::to_value(&observation).map_err(|error| error.to_string())?;
            let marker_value =
                serde_json::to_value(observation.marker).map_err(|error| error.to_string())?;
            let mut projection = json!({
                "observation": observation_value,
                "marker": marker_value,
                "allowed": false
            });
            match observation.as_tumour_claim() {
                Ok(claim) => {
                    let claim_value =
                        serde_json::to_value(&claim).map_err(|error| error.to_string())?;
                    projection["allowed"] = json!(true);
                    projection["outcome_kind"] = claim_value
                        .get("tumour_claim")
                        .cloned()
                        .unwrap_or(Value::Null);
                    projection["tumour_claim"] = claim_value;
                    projection["refusal"] = Value::Null;
                    projection["refusal_kind"] = Value::Null;
                }
                Err(refusal) => {
                    let refusal_value =
                        serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                    projection["outcome_kind"] = json!("refused");
                    projection["refusal"] = refusal_value.clone();
                    projection["refusal_kind"] = refusal_value["refusal"].clone();
                    projection["refusal_text"] = json!(refusal.to_string());
                }
            }
            checks.insert("promotion".into(), projection);
        }

        if let Some(value) = arguments.get("resistance") {
            let object = value.as_object().ok_or("resistance must be an object")?;
            let diagnosis: SpecimenObservation = serde_json::from_value(
                object
                    .get("diagnosis")
                    .cloned()
                    .ok_or("resistance.diagnosis is required")?,
            )
            .map_err(|error| format!("invalid resistance diagnosis observation: {error}"))?;
            let recurrence: SpecimenObservation = serde_json::from_value(
                object
                    .get("recurrence")
                    .cloned()
                    .ok_or("resistance.recurrence is required")?,
            )
            .map_err(|error| format!("invalid resistance recurrence observation: {error}"))?;
            let explanations = onco_explain_new_alteration(&diagnosis, &recurrence);
            let sole = explanations.sole();
            let mut projection = json!({
                "diagnosis": serde_json::to_value(&diagnosis).map_err(|error| error.to_string())?,
                "recurrence": serde_json::to_value(&recurrence).map_err(|error| error.to_string())?,
                "not_excluded": serde_json::to_value(&explanations.not_excluded).map_err(|error| error.to_string())?,
                "excluded": explanations.excluded,
                "de_novo_emergence_survives": explanations.contains(
                    bioprism_oncoworlds::ResistanceExplanation::DeNovoEmergence
                ),
                "allowed": sole.is_ok(),
                "outcome_kind": if sole.is_ok() { "unique" } else { "ambiguous" }
            });
            match sole {
                Ok(explanation) => {
                    projection["unique_explanation"] =
                        serde_json::to_value(explanation).map_err(|error| error.to_string())?;
                    projection["refusal"] = Value::Null;
                    projection["refusal_kind"] = Value::Null;
                }
                Err(refusal) => {
                    let refusal_value =
                        serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                    projection["refusal"] = refusal_value.clone();
                    projection["refusal_kind"] = refusal_value["refusal"].clone();
                    projection["refusal_text"] = json!(refusal.to_string());
                }
            }
            checks.insert("resistance".into(), projection);
        }

        if let Some(value) = arguments.get("attribution") {
            let object = value.as_object().ok_or("attribution must be an object")?;
            let treatment = object
                .get("treatment")
                .and_then(Value::as_str)
                .ok_or("attribution.treatment must be a string")?;
            if treatment.len() > 10_000 {
                return Err("attribution treatment exceeds the 10000-byte safety bound".into());
            }
            let alteration: MolecularMarker = serde_json::from_value(
                object
                    .get("alteration")
                    .cloned()
                    .ok_or("attribution.alteration is required")?,
            )
            .map_err(|error| format!("invalid treatment-attribution alteration: {error}"))?;
            let design: CausalDesign = serde_json::from_value(
                object
                    .get("design")
                    .cloned()
                    .ok_or("attribution.design is required")?,
            )
            .map_err(|error| format!("invalid treatment-attribution design: {error}"))?;
            let result = onco_attribute_to_treatment(treatment, alteration, design);
            let mut projection = json!({
                "treatment": treatment,
                "alteration": alteration,
                "alteration_label": alteration.describe(),
                "design": design,
                "allowed": result.is_ok()
            });
            let refusal = result.expect_err("temporal-attribution design is always refused");
            let refusal_value =
                serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
            projection["refusal"] = refusal_value.clone();
            projection["refusal_kind"] = refusal_value["refusal"].clone();
            projection["refusal_text"] = json!(refusal.to_string());
            checks.insert("attribution".into(), projection);
        }

        if checks.is_empty() {
            return Err("at least one clonal evidence section is required".into());
        }
        if checks.len() > 3 {
            return Err("clonal evidence checks may contain at most three sections".into());
        }
        let refusal_count = checks
            .values()
            .filter(|value| value.get("allowed") == Some(&json!(false)))
            .count();
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/oncoworlds-clonal-evidence-check/0.1",
            "outcome_kind": "report",
            "all_admissible": refusal_count == 0,
            "check_count": checks.len(),
            "refusal_count": refusal_count,
            "checks": checks,
            "guarantees": [
                "specimen presence promotes only to a claim over sampled tumour material",
                "negative and below-detection observations retain their assay limit and sampled regions",
                "resistance explanations remain set-valued and recurrence selection is not rewritten as de novo biology",
                "temporal association is never upgraded to treatment causation"
            ],
            "limitations": [
                "no phylogeny is inferred, no allele-fraction conversion is performed, and no causal effect is estimated",
                "a unique explanation would still be an arithmetic survivor, not proof of biological history",
                "these checks do not diagnose, classify, or recommend treatment"
            ]
        }))
    }

    fn oncoworlds_era_shift_check(&self, arguments: &Value) -> Result<Value, String> {
        let left: OncoShiftCohort = serde_json::from_value(
            arguments
                .get("left")
                .cloned()
                .ok_or("left is required and must be a serialized OncoWorlds Cohort")?,
        )
        .map_err(|error| format!("invalid left OncoWorlds cohort: {error}"))?;
        let right: OncoShiftCohort = serde_json::from_value(
            arguments
                .get("right")
                .cloned()
                .ok_or("right is required and must be a serialized OncoWorlds Cohort")?,
        )
        .map_err(|error| format!("invalid right OncoWorlds cohort: {error}"))?;
        if left.entities.len() > 10_000 || right.entities.len() > 10_000 {
            return Err("OncoWorlds cohort entity sets exceed the 10000-label safety bound".into());
        }
        let mapping: Option<EntityMapping> = arguments
            .get("mapping")
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .map_err(|error| format!("invalid OncoWorlds entity mapping: {error}"))?;
        if mapping
            .as_ref()
            .is_some_and(|item| item.fate_count() > 10_000)
        {
            return Err("OncoWorlds entity mapping exceeds the 10000-label safety bound".into());
        }
        let assays: Vec<SiteAssayContext> = arguments
            .get("assay_contexts")
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .map_err(|error| format!("invalid site assay contexts: {error}"))?
            .unwrap_or_default();
        if assays.len() > 100 {
            return Err("site assay context panel exceeds the 100-context safety bound".into());
        }
        let assay_projections: Vec<Value> = assays
            .iter()
            .map(|context| {
                let availability = serde_json::to_value(&context.availability)
                    .map_err(|error| error.to_string())?;
                let observation = serde_json::to_value(context.observation())
                    .map_err(|error| error.to_string())?;
                let refusal =
                    onco_as_negative_call(context).expect_err("negative conversion always refuses");
                let refusal_value =
                    serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                Ok(json!({
                    "site": context.site,
                    "assay": context.assay,
                    "availability": availability,
                    "observation": observation,
                    "negative_call_supported": false,
                    "negative_call_refusal": refusal_value,
                    "negative_call_refusal_kind": refusal_value["refusal"]
                }))
            })
            .collect::<Result<_, String>>()?;
        let descriptor_values = arguments
            .get("descriptor_checks")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        if descriptor_values.len() > 100 {
            return Err(
                "population descriptor check panel exceeds the 100-check safety bound".into(),
            );
        }
        let descriptor_projections: Vec<Value> = descriptor_values
            .iter()
            .map(|value| {
                let descriptor: PopulationDescriptor = serde_json::from_value(
                    value
                        .get("descriptor")
                        .cloned()
                        .ok_or("descriptor check requires descriptor")?,
                )
                .map_err(|error| format!("invalid population descriptor: {error}"))?;
                let use_: DescriptorUse = serde_json::from_value(
                    value
                        .get("use")
                        .cloned()
                        .ok_or("descriptor check requires use")?,
                )
                .map_err(|error| format!("invalid population descriptor use: {error}"))?;
                let descriptor_value =
                    serde_json::to_value(descriptor).map_err(|error| error.to_string())?;
                let use_value = serde_json::to_value(use_).map_err(|error| error.to_string())?;
                match onco_use_descriptor(descriptor, use_) {
                    Ok(()) => Ok(json!({
                        "descriptor": descriptor_value,
                        "descriptor_label": descriptor.as_str(),
                        "use": use_value,
                        "use_label": use_.as_str(),
                        "administrative": descriptor.is_administrative(),
                        "allowed": true
                    })),
                    Err(refusal) => {
                        let refusal_value =
                            serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                        Ok(json!({
                            "descriptor": descriptor_value,
                            "descriptor_label": descriptor.as_str(),
                            "use": use_value,
                            "use_label": use_.as_str(),
                            "administrative": descriptor.is_administrative(),
                            "allowed": false,
                            "refusal": refusal_value,
                            "refusal_kind": refusal_value["refusal"],
                            "refusal_text": refusal.to_string()
                        }))
                    }
                }
            })
            .collect::<Result<_, String>>()?;
        let left_value = serde_json::to_value(&left).map_err(|error| error.to_string())?;
        let right_value = serde_json::to_value(&right).map_err(|error| error.to_string())?;
        let mapping_value = mapping
            .as_ref()
            .map(serde_json::to_value)
            .transpose()
            .map_err(|error| error.to_string())?;
        let same_classification_version =
            left.classification_version == right.classification_version;
        let mapping_versions_match = mapping.as_ref().is_some_and(|item| {
            (item.from == left.classification_version && item.to == right.classification_version)
                || (item.from == right.classification_version
                    && item.to == left.classification_version)
        });
        let shared = json!({
            "left": left_value,
            "right": right_value,
            "mapping": mapping_value,
            "mapping_declared": mapping.is_some(),
            "mapping_fate_count": mapping.as_ref().map(EntityMapping::fate_count).unwrap_or(0),
            "mapping_versions_match": mapping_versions_match,
            "same_classification_version": same_classification_version,
            "left_entity_count": left.entities.len(),
            "right_entity_count": right.entities.len(),
            "assay_contexts": assay_projections,
            "assay_context_count": assays.len(),
            "descriptor_checks": descriptor_projections,
            "descriptor_check_count": descriptor_values.len()
        });
        match onco_comparable_cohorts(&left, &right, mapping.as_ref()) {
            Ok(()) => Ok(json!({
                "ok": true,
                "schema": "bioprism-mcp/oncoworlds-era-shift-check/0.1",
                "outcome_kind": "comparable",
                "comparable": true,
                "evidence": shared,
                "guarantees": [
                    "same-version cohorts do not require an invented mapping",
                    "cross-version comparison requires a stated mapping covering every label present in the older cohort",
                    "resource absence remains not-collected and never becomes a negative molecular call",
                    "administrative population descriptors may stratify a report but do not become biological mechanisms"
                ],
                "limitations": [
                    "label mappings are caller-declared and no classification semantics are inferred",
                    "assay and descriptor checks are evidence projections; no assay is run and no biological effect is estimated"
                ]
            })),
            Err(refusal) => {
                let refusal_value =
                    serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                Ok(json!({
                    "ok": false,
                    "schema": "bioprism-mcp/oncoworlds-era-shift-check/0.1",
                    "outcome_kind": "refused",
                    "stage": "classification_era_comparability",
                    "comparable": false,
                    "refusal_kind": refusal_value["refusal"],
                    "refusal": refusal_value,
                    "refusal_text": refusal.to_string(),
                    "fail_closed": true,
                    "evidence": shared,
                    "guarantee": "an unmapped era change, incomplete label mapping, or unsupported shift descriptor never becomes a comparable cohort claim"
                }))
            }
        }
    }

    fn oncoworlds_equity_check(&self, arguments: &Value) -> Result<Value, String> {
        let pooled: PooledScore = serde_json::from_value(
            arguments
                .get("pooled")
                .cloned()
                .ok_or("pooled is required and must be a serialized PooledScore")?,
        )
        .map_err(|error| format!("invalid pooled score: {error}"))?;
        if pooled.subgroups.len() > 10_000 {
            return Err("equity subgroup panel exceeds the 10000-subgroup safety bound".into());
        }
        let pooled_value = pooled.value;
        let subgroup_count = pooled.subgroups.len();
        let interval_count = pooled
            .subgroups
            .iter()
            .filter(|subgroup| subgroup.interval.is_some())
            .count();
        let subgroup_values: Vec<Value> = pooled
            .subgroups
            .iter()
            .map(serde_json::to_value)
            .collect::<Result<_, _>>()
            .map_err(|error| error.to_string())?;
        match onco_equity_report(pooled) {
            Ok(report) => {
                let claims: Vec<Value> = report
                    .subgroups()
                    .iter()
                    .map(|claim| serde_json::to_value(claim.result()))
                    .collect::<Result<_, _>>()
                    .map_err(|error| error.to_string())?;
                Ok(json!({
                    "ok": true,
                    "schema": "bioprism-mcp/oncoworlds-equity-check/0.1",
                    "outcome_kind": "equity_report",
                    "equity_supported": true,
                    "pooled_value": report.pooled(),
                    "subgroups": claims,
                    "subgroup_count": subgroup_count,
                    "interval_count": interval_count,
                    "all_intervals_present": interval_count == subgroup_count,
                    "report": report,
                    "guarantees": [
                        "a pooled score is never released as an equity claim without every subgroup result",
                        "each published subgroup carries its own sample size and uncertainty interval",
                        "small subgroups are not silently discarded; their instability remains visible in the interval"
                    ],
                    "limitations": [
                        "the endpoint does not compute estimates, intervals, calibration, or fairness metrics",
                        "an interval is evidence of uncertainty, not proof of parity or absence of bias"
                    ]
                }))
            }
            Err(refusal) => {
                let refusal_value =
                    serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                Ok(json!({
                    "ok": false,
                    "schema": "bioprism-mcp/oncoworlds-equity-check/0.1",
                    "outcome_kind": "refused",
                    "stage": "equity_report",
                    "equity_supported": false,
                    "refusal_kind": refusal_value["refusal"],
                    "refusal": refusal_value,
                    "refusal_text": refusal.to_string(),
                    "fail_closed": true,
                    "pooled_value": pooled_value,
                    "subgroups": subgroup_values,
                    "subgroup_count": subgroup_count,
                    "interval_count": interval_count,
                    "all_intervals_present": interval_count == subgroup_count,
                    "guarantee": "a pooled-only, empty, or unquantified subgroup result never becomes an equity claim"
                }))
            }
        }
    }

    fn oncoworlds_entity_world_check(&self, arguments: &Value) -> Result<Value, String> {
        let mut checks = serde_json::Map::new();

        if let Some(value) = arguments.get("provenance") {
            let object = value.as_object().ok_or("provenance must be an object")?;
            let left: TissueProvenance = serde_json::from_value(
                object
                    .get("left")
                    .cloned()
                    .ok_or("provenance.left is required")?,
            )
            .map_err(|error| format!("invalid left tissue provenance: {error}"))?;
            let right: TissueProvenance = serde_json::from_value(
                object
                    .get("right")
                    .cloned()
                    .ok_or("provenance.right is required")?,
            )
            .map_err(|error| format!("invalid right tissue provenance: {error}"))?;
            let selection_modelled = object
                .get("selection_modelled")
                .and_then(Value::as_bool)
                .ok_or("provenance.selection_modelled must be a boolean")?;
            let result = onco_pool_provenance(left, right, selection_modelled);
            let mut projection = json!({
                "left": left,
                "right": right,
                "left_label": left.as_str(),
                "right_label": right.as_str(),
                "selection_modelled": selection_modelled,
                "allowed": result.is_ok()
            });
            if let Err(refusal) = result {
                let refusal_value =
                    serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                projection["refusal"] = refusal_value.clone();
                projection["refusal_kind"] = refusal_value["refusal"].clone();
                projection["refusal_text"] = json!(refusal.to_string());
            } else {
                projection["refusal"] = Value::Null;
                projection["refusal_kind"] = Value::Null;
            }
            checks.insert("provenance".into(), projection);
        }

        if let Some(value) = arguments.get("alterations") {
            let object = value.as_object().ok_or("alterations must be an object")?;
            let left: AlterationMechanism = serde_json::from_value(
                object
                    .get("left")
                    .cloned()
                    .ok_or("alterations.left is required")?,
            )
            .map_err(|error| format!("invalid left alteration mechanism: {error}"))?;
            let right: AlterationMechanism = serde_json::from_value(
                object
                    .get("right")
                    .cloned()
                    .ok_or("alterations.right is required")?,
            )
            .map_err(|error| format!("invalid right alteration mechanism: {error}"))?;
            let estimand = object.get("estimand").and_then(Value::as_str);
            let result = onco_pool_alterations(left, right, estimand);
            let mut projection = json!({
                "left": left,
                "right": right,
                "left_label": left.as_str(),
                "right_label": right.as_str(),
                "estimand": estimand,
                "estimand_declared": estimand.is_some_and(|text| !text.trim().is_empty()),
                "allowed": result.is_ok()
            });
            if let Err(refusal) = result {
                let refusal_value =
                    serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                projection["refusal"] = refusal_value.clone();
                projection["refusal_kind"] = refusal_value["refusal"].clone();
                projection["refusal_text"] = json!(refusal.to_string());
            } else {
                projection["refusal"] = Value::Null;
                projection["refusal_kind"] = Value::Null;
            }
            checks.insert("alterations".into(), projection);
        }

        if let Some(value) = arguments.get("benchmark") {
            let object = value.as_object().ok_or("benchmark must be an object")?;
            let macro_score = object
                .get("macro_score")
                .and_then(Value::as_f64)
                .ok_or("benchmark.macro_score must be a number")?;
            let counts: std::collections::BTreeMap<String, usize> = serde_json::from_value(
                object
                    .get("per_class_counts")
                    .cloned()
                    .ok_or("benchmark.per_class_counts is required")?,
            )
            .map_err(|error| format!("invalid per-class counts: {error}"))?;
            if counts.len() > 10_000 {
                return Err("benchmark class counts exceed the 10000-class safety bound".into());
            }
            let report = RarePerformanceReport {
                macro_score,
                per_class_counts: counts.clone(),
            };
            let report_value = serde_json::to_value(&report).map_err(|error| error.to_string())?;
            let mut projection = json!({
                "macro_score": macro_score,
                "per_class_counts": counts,
                "class_count": report.per_class_counts.len(),
                "zero_case_classes": report.per_class_counts.iter().filter_map(|(class, count)| (*count == 0).then_some(class)).collect::<Vec<_>>(),
                "report": report_value,
                "allowed": false,
                "published": Value::Null
            });
            match report.publish() {
                Ok(published) => {
                    let feasibility = serde_json::to_value(published.feasibility())
                        .map_err(|error| error.to_string())?;
                    projection["allowed"] = json!(true);
                    projection["published"] =
                        serde_json::to_value(&published).map_err(|error| error.to_string())?;
                    projection["feasibility"] = feasibility.clone();
                    projection["feasibility_kind"] = feasibility["feasibility"].clone();
                    projection["refusal"] = Value::Null;
                    projection["refusal_kind"] = Value::Null;
                }
                Err(refusal) => {
                    let refusal_value =
                        serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                    projection["refusal"] = refusal_value.clone();
                    projection["refusal_kind"] = refusal_value["refusal"].clone();
                    projection["refusal_text"] = json!(refusal.to_string());
                }
            }
            checks.insert("benchmark".into(), projection);
        }

        if let Some(value) = arguments.get("lesion_analysis") {
            let object = value
                .as_object()
                .ok_or("lesion_analysis must be an object")?;
            let set = LesionSet {
                lesions: object
                    .get("lesions")
                    .and_then(Value::as_u64)
                    .ok_or("lesion_analysis.lesions must be a non-negative integer")?
                    as usize,
                participants: object
                    .get("participants")
                    .and_then(Value::as_u64)
                    .ok_or("lesion_analysis.participants must be a non-negative integer")?
                    as usize,
            };
            if set.lesions > 1_000_000 || set.participants > 1_000_000 {
                return Err(
                    "lesion analysis counts exceed the 1000000-subject safety bound".into(),
                );
            }
            let cluster_declared = object
                .get("cluster_declared")
                .and_then(Value::as_bool)
                .ok_or("lesion_analysis.cluster_declared must be a boolean")?;
            let endpoint: LesionEndpoint = serde_json::from_value(
                object
                    .get("endpoint")
                    .cloned()
                    .ok_or("lesion_analysis.endpoint is required")?,
            )
            .map_err(|error| format!("invalid lesion endpoint: {error}"))?;
            let event: FollowUpEvent = serde_json::from_value(
                object
                    .get("event")
                    .cloned()
                    .ok_or("lesion_analysis.event is required")?,
            )
            .map_err(|error| format!("invalid follow-up event: {error}"))?;
            let handling: EventHandling = serde_json::from_value(
                object
                    .get("handling")
                    .cloned()
                    .ok_or("lesion_analysis.handling is required")?,
            )
            .map_err(|error| format!("invalid event handling: {error}"))?;
            let cluster_result = onco_declare_cluster(set, cluster_declared);
            let event_result = onco_handle_event(endpoint, event, handling);
            let mut projection = json!({
                "lesions": set.lesions,
                "participants": set.participants,
                "cluster_declared": cluster_declared,
                "cluster_allowed": cluster_result.is_ok(),
                "endpoint": endpoint,
                "event": event,
                "handling": handling,
                "event_allowed": event_result.is_ok(),
                "allowed": cluster_result.is_ok() && event_result.is_ok()
            });
            if let Err(refusal) = cluster_result {
                let refusal_value =
                    serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                projection["cluster_refusal"] = refusal_value.clone();
                projection["cluster_refusal_kind"] = refusal_value["refusal"].clone();
                projection["cluster_refusal_text"] = json!(refusal.to_string());
            } else {
                projection["cluster_refusal"] = Value::Null;
                projection["cluster_refusal_kind"] = Value::Null;
            }
            if let Err(refusal) = event_result {
                let refusal_value =
                    serde_json::to_value(&refusal).map_err(|error| error.to_string())?;
                projection["event_refusal"] = refusal_value.clone();
                projection["event_refusal_kind"] = refusal_value["refusal"].clone();
                projection["event_refusal_text"] = json!(refusal.to_string());
            } else {
                projection["event_refusal"] = Value::Null;
                projection["event_refusal_kind"] = Value::Null;
            }
            checks.insert("lesion_analysis".into(), projection);
        }

        if checks.is_empty() {
            return Err("at least one entity-world check section is required".into());
        }
        if checks.len() > 4 {
            return Err("entity-world checks may contain at most four sections".into());
        }
        let refusal_count = checks
            .values()
            .filter(|value| value.get("allowed") == Some(&json!(false)))
            .count();
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/oncoworlds-entity-world-check/0.1",
            "outcome_kind": "report",
            "all_admissible": refusal_count == 0,
            "check_count": checks.len(),
            "refusal_count": refusal_count,
            "checks": checks,
            "guarantees": [
                "provenance selection is explicit before diagnostic, recurrence, and postmortem material is pooled",
                "different alteration mechanisms require a stated estimand rather than pathway-level collapse",
                "rare-class macro performance retains per-class counts and zero-case feasibility findings",
                "lesion analyses declare participant clustering and systemic death is not silently censored for local control"
            ],
            "limitations": [
                "the tool checks declared evidence and does not estimate effect sizes, survival, competing-risk curves, or fairness metrics",
                "a permitted section is a structural admissibility result, not biological truth or clinical authorization"
            ]
        }))
    }

    fn stress_profile(&self, arguments: &Value) -> Result<Value, String> {
        let cohort: Cohort = serde_json::from_value(
            arguments
                .get("cohort")
                .cloned()
                .ok_or("cohort is required and must be a serialized stress Cohort")?,
        )
        .map_err(|error| format!("invalid stress cohort: {error}"))?;
        if cohort.subjects.len() > 10_000 {
            return Err("cohort exceeds the 10000-subject safety bound".into());
        }
        let stress: Stress = serde_json::from_value(
            arguments
                .get("stress")
                .cloned()
                .ok_or("stress is required and must be a serialized Stress")?,
        )
        .map_err(|error| format!("invalid stress: {error}"))?;
        let procedures: Vec<Procedure> = match arguments.get("procedures") {
            None => standard_panel(),
            Some(value) => serde_json::from_value(value.clone())
                .map_err(|error| format!("invalid stress procedures: {error}"))?,
        };
        if procedures.len() > 100 {
            return Err("stress procedure panel exceeds the 100-procedure safety bound".into());
        }
        match stress_profile_run(&cohort, &stress, &procedures) {
            Ok(profile) => Ok(json!({
                "ok": true,
                "headline": profile.headline(),
                "profile": profile,
                "guarantees": [
                    "breaking points are reported on the declared intensity ladder rather than collapsed into a survival score",
                    "generator defects and batch confounding suppress robustness claims instead of being scored as findings",
                    "effective sample size, unresolved subjects, and analysable prevalence remain visible at every rung"
                ],
                "limitations": [
                    "procedures are closed-form reference summaries; no model is fitted",
                    "the profile is conditional on this cohort, stress seed, family, and finite intensity ladder"
                ]
            })),
            Err(error) => Ok(json!({
                "ok": false,
                "stage": "stress_profile",
                "refusal": error.to_string(),
                "fail_closed": true,
                "guarantee": "invalid cohorts, undefined conclusions, confounded stresses, and broken postconditions never become a robustness claim"
            })),
        }
    }

    fn stress_report(&self, arguments: &Value) -> Result<Value, String> {
        let cohort: Cohort = serde_json::from_value(
            arguments
                .get("cohort")
                .cloned()
                .ok_or("cohort is required and must be a serialized stress Cohort")?,
        )
        .map_err(|error| format!("invalid stress cohort: {error}"))?;
        if cohort.subjects.len() > 10_000 {
            return Err("cohort exceeds the 10000-subject safety bound".into());
        }
        let raw_stresses = arguments
            .get("stresses")
            .cloned()
            .ok_or("stresses is required and must be an array of Stress values")?;
        let stresses: Vec<Stress> = serde_json::from_value(raw_stresses)
            .map_err(|error| format!("invalid stress list: {error}"))?;
        if stresses.len() > 100 {
            return Err("stress program exceeds the 100-stress safety bound".into());
        }
        let procedures: Vec<Procedure> = match arguments.get("procedures") {
            None => standard_panel(),
            Some(value) => serde_json::from_value(value.clone())
                .map_err(|error| format!("invalid stress procedures: {error}"))?,
        };
        if procedures.len() > 100 {
            return Err("stress procedure panel exceeds the 100-procedure safety bound".into());
        }
        match StressReport::run(&cohort, &stresses, &procedures) {
            Ok(report) => Ok(json!({
                "ok": true,
                "headline": report.headline(),
                "worst_family": report.worst_family(),
                "report": report,
                "guarantees": [
                    "each family remains a separate robustness profile",
                    "the worst-family view excludes non-identifiable and generator-defective profiles",
                    "a report never turns a required relation failure into a fragile biological conclusion"
                ],
                "limitations": [
                    "family magnitudes are comparable only as declared endpoint fractions, not as physical units",
                    "no causal graph, preanalytic lifecycle, or ontology-drift stress is inferred beyond the supplied program"
                ]
            })),
            Err(error) => Ok(json!({
                "ok": false,
                "stage": "stress_report",
                "refusal": error.to_string(),
                "fail_closed": true,
                "guarantee": "a partial stress program never becomes an apparently complete report"
            })),
        }
    }

    fn oracle_combine(&self, arguments: &Value) -> Result<Value, String> {
        let subject = arguments
            .get("subject")
            .and_then(Value::as_str)
            .ok_or("subject is required")?;
        if subject.trim().is_empty() {
            return Err("subject must not be empty".into());
        }
        let at = arguments
            .get("at")
            .and_then(Value::as_str)
            .ok_or("at is required in YYYY-MM-DDTHH:MM:SSZ form")?;
        let at = UtcTimestamp::parse(at).map_err(|error| error.to_string())?;
        let values = arguments
            .get("judgements")
            .and_then(Value::as_array)
            .ok_or("judgements is required and must be an array")?;
        if values.is_empty() || values.len() > 1_000 {
            return Err("judgements must contain between 1 and 1000 entries".into());
        }
        let judgements: Vec<Judgement> = values
            .iter()
            .cloned()
            .map(|value| {
                serde_json::from_value(value)
                    .map_err(|error| format!("invalid oracle judgement: {error}"))
            })
            .collect::<Result<_, _>>()?;
        let minimum = arguments
            .get("minimum_deciding_tier")
            .and_then(Value::as_str)
            .map(|value| {
                serde_json::from_value::<OracleEvidenceTier>(json!(value))
                    .map_err(|error| format!("invalid minimum_deciding_tier: {error}"))
            })
            .transpose()?
            .unwrap_or(OracleEvidenceTier::Judge);
        let policy = MeshPolicy::new(minimum);
        let verdict = policy.combine(subject, &at, judgements);
        let max_items = arguments
            .get("max_items")
            .and_then(Value::as_u64)
            .unwrap_or(100);
        if max_items == 0 || max_items > 1_000 {
            return Err("max_items must be between 1 and 1000".into());
        }
        let max_items = max_items as usize;
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/oracle-combine/0.1",
            "subject": verdict.subject,
            "at": verdict.at,
            "status": verdict.status(),
            "underdetermined": verdict.is_underdetermined(),
            "deciding_tier": verdict.deciding_tier(),
            "judge_only": verdict.is_judge_only(),
            "suppressed_override": verdict.has_suppressed_override(),
            "acceptable": verdict.acceptable,
            "basis": verdict.basis,
            "confidence": verdict.confidence,
            "establishes": verdict.establishes(),
            "does_not_establish": verdict.does_not_establish(),
            "contributing": verdict.contributing.iter().take(max_items).collect::<Vec<_>>(),
            "omitted_contributing": verdict.contributing.len().saturating_sub(max_items),
            "withheld": verdict.withheld.iter().take(max_items).collect::<Vec<_>>(),
            "omitted_withheld": verdict.withheld.len().saturating_sub(max_items),
            "inadmissible": verdict.inadmissible.iter().take(max_items).collect::<Vec<_>>(),
            "omitted_inadmissible": verdict.inadmissible.len().saturating_sub(max_items),
            "suppressed": verdict.suppressed.iter().take(max_items).collect::<Vec<_>>(),
            "omitted_suppressed": verdict.suppressed.len().saturating_sub(max_items),
            "disagreements": verdict.disagreements.iter().take(max_items).collect::<Vec<_>>(),
            "omitted_disagreements": verdict.disagreements.len().saturating_sub(max_items),
            "guarantees": [
                "evidence tier, not confidence, determines which judgements may decide",
                "same-tier disagreement remains set-valued and underdetermined rather than becoming a majority vote",
                "expired, superseded, out-of-scope, and weaker judgements remain visible in separate ledgers",
            ],
            "limitations": [
                "judgements are caller-supplied and this tool does not run an oracle, sandbox an evaluator, or authenticate provenance",
                "the mesh combines positions; it does not infer biological truth, adjudicate a disputed result, or manufacture missing evidence",
            ]
        }))
    }

    fn policy_screen(&self, arguments: &Value) -> Result<Value, String> {
        let relative = arguments
            .get("world")
            .and_then(Value::as_str)
            .ok_or("world is required (a JSON world document relative to the server root)")?;
        let path = self.resolve(relative)?;
        if path.is_dir() {
            return Err(
                "policy_screen requires a JSON world document, not an indexed store".into(),
            );
        }
        let world = World::from_json(self.read_json(&path)?).map_err(|error| error.to_string())?;
        let request_value = arguments
            .get("request")
            .cloned()
            .ok_or("request is required and must bind principal, purpose, channel and at")?;
        let request: PolicyRequest = serde_json::from_value(request_value)
            .map_err(|error| format!("invalid policy request: {error}"))?;

        let mut lattice = PolicyLattice::new();
        if let Some(rules) = arguments.get("rules") {
            let rules = rules
                .as_array()
                .ok_or("rules must be an array of policy rule objects")?;
            for (index, raw_rule) in rules.iter().enumerate() {
                let rule: PolicyRule = serde_json::from_value(raw_rule.clone())
                    .map_err(|error| format!("invalid policy rule at index {index}: {error}"))?;
                lattice.register(rule).map_err(|error| {
                    format!("cannot register policy rule at index {index}: {error}")
                })?;
            }
        }
        if let Some(tags) = arguments.get("tags") {
            let tags = tags
                .as_object()
                .ok_or("tags must be an object mapping tag names to policy labels")?;
            for (tag, raw_label) in tags {
                let label: PolicyLabel = serde_json::from_value(raw_label.clone())
                    .map_err(|error| format!("invalid policy label for tag {tag:?}: {error}"))?;
                lattice.register_tag(tag.clone(), label);
            }
        }

        let selected: Vec<&bioprism_world::Fact> = match arguments.get("facts") {
            None => world.facts.iter().collect(),
            Some(raw_facts) => {
                let ids = raw_facts
                    .as_array()
                    .ok_or("facts must be an array of fact ids")?;
                let mut selected = Vec::with_capacity(ids.len());
                let mut seen = BTreeSet::new();
                for raw_id in ids {
                    let id = raw_id
                        .as_str()
                        .ok_or("facts must be an array of fact ids")?;
                    if !seen.insert(id) {
                        return Err(format!("facts must not contain duplicate id {id:?}"));
                    }
                    selected.push(
                        world
                            .fact(id)
                            .ok_or_else(|| format!("fact {id:?} is not present in the world"))?,
                    );
                }
                selected
            }
        };
        let selected_ids = selected
            .iter()
            .map(|fact| fact.id.as_str().to_string())
            .collect::<Vec<_>>();
        let unregistered_tags = selected
            .iter()
            .map(|fact| {
                json!({
                    "fact_id": fact.id.as_str(),
                    "tags": lattice.unregistered_tags(fact),
                })
            })
            .filter(|item| item["tags"].as_array().is_some_and(|tags| !tags.is_empty()))
            .collect::<Vec<_>>();

        let screening = lattice.screen(selected.iter().copied(), &request);
        let admitted = screening
            .admitted
            .iter()
            .map(|item| {
                json!({
                    "fact_id": item.fact.id.as_str(),
                    "admission": item.admission,
                })
            })
            .collect::<Vec<_>>();
        let refused = screening
            .refused
            .iter()
            .map(|item| {
                json!({
                    "fact_id": item.fact_id,
                    "refusal": item.refusal,
                    "constraint": item.refusal.constraint(),
                    "escalatable": item.refusal.is_escalatable(),
                })
            })
            .collect::<Vec<_>>();
        let complete = screening.is_complete();
        let refusal_count = screening.refused.len();
        Ok(json!({
            "ok": true,
            "world": relative,
            "world_id": world.world_id,
            "world_sha256": world.content_hash(),
            "policy_version": lattice.version(),
            "request": request,
            "selected_facts": selected_ids,
            "candidate_count": selected.len(),
            "admitted_count": admitted.len(),
            "refused_count": refusal_count,
            "admitted": admitted,
            "refused": refused,
            "complete": complete,
            "derived_label": screening.derived_label(),
            "obligations": screening.obligations(),
            "trace": screening.trace.to_json(),
            "unregistered_tags": unregistered_tags,
            "guarantees": {
                "screened_before_selection": true,
                "unknown_policy_denies_by_default": true,
                "refusals_are_retained": true,
                "obligations_are_declared_not_discharged": true,
            },
        }))
    }

    fn bioethics_action_review(&self, arguments: &Value) -> Result<Value, String> {
        let raw_plan = arguments
            .get("plan")
            .cloned()
            .ok_or("plan is required and must be a serialized bioprism-bioethics ActionPlan")?;
        let plan: ActionPlan = serde_json::from_value(raw_plan)
            .map_err(|error| format!("invalid action plan: {error}"))?;
        if plan.steps.len() > 10_000 {
            return Err("plan may contain at most 10000 steps".into());
        }

        let boundary = match arguments.get("boundary") {
            Some(raw) => serde_json::from_value(raw.clone())
                .map_err(|error| format!("invalid research boundary: {error}"))?,
            None => ResearchBoundary::research_only(),
        };
        let disposition = match plan.partition(&boundary) {
            Ok(disposition) => disposition,
            Err(error) => {
                return Ok(json!({
                    "ok": false,
                    "stage": "research_boundary",
                    "refusal": error.to_string(),
                    "fail_closed": true,
                    "guarantee": "a clinical use refuses the complete plan before physical or in-silico steps are separated"
                }))
            }
        };

        let physical_step_count = disposition.physical_steps().len();
        let in_silico_step_count = disposition.in_silico_steps().len();
        let referral = if disposition.requires_physical_authorisation() {
            match arguments.get("authorisation") {
                None => json!({
                    "status": "not_attempted",
                    "refusal": "physical steps require both human approval and institutional safety review before referral",
                    "fail_closed": true,
                }),
                Some(raw) => {
                    let authorisation: Authorisation = serde_json::from_value(raw.clone())
                        .map_err(|error| format!("invalid action authorisation: {error}"))?;
                    match refer_physical_action(&disposition, &authorisation) {
                        Ok(referral) => json!({
                            "status": "referred",
                            "referral": referral,
                            "statement": bioprism_bioethics::action::PhysicalReferral::STATEMENT,
                            "executes_physical_action": false,
                        }),
                        Err(error) => json!({
                            "status": "refused",
                            "refusal": error.to_string(),
                            "fail_closed": true,
                            "executes_physical_action": false,
                        }),
                    }
                }
            }
        } else {
            json!({
                "status": "not_required",
                "refusal": null,
                "executes_physical_action": false,
            })
        };

        Ok(json!({
            "ok": true,
            "subject": disposition.subject(),
            "declared_use": plan.declared_use,
            "permitted_uses": boundary.permitted(),
            "disposition": disposition,
            "physical_step_count": physical_step_count,
            "in_silico_step_count": in_silico_step_count,
            "requires_external_authorisation": physical_step_count > 0,
            "referral": referral,
            "guarantees": [
                "clinical-use refusal happens before plan partitioning",
                "physical actions are only represented as a referral and are never executed",
                "missing or incomplete human authorisation remains a typed refusal",
            ],
        }))
    }

    fn bioethics_human_subject_screen(&self, arguments: &Value) -> Result<Value, String> {
        let raw_study = arguments
            .get("study")
            .cloned()
            .ok_or("study is required and must be a serialized StudyDescription")?;
        let study: StudyDescription = serde_json::from_value(raw_study)
            .map_err(|error| format!("invalid study description: {error}"))?;
        if study.engagements.len() > 100 {
            return Err("study may declare at most 100 engagement kinds".into());
        }

        let determination = screen_human_subject(&study);
        let consent_check = match (arguments.get("consent"), arguments.get("at")) {
            (None, None) => json!({
                "status": "not_run",
                "reason": "provide both consent and at to check every declared purpose",
            }),
            (Some(_), None) | (None, Some(_)) => {
                return Err("consent and at must be supplied together".into())
            }
            (Some(raw_consent), Some(raw_at)) => {
                let consent: bioprism_policy::Consent = serde_json::from_value(raw_consent.clone())
                    .map_err(|error| format!("invalid consent: {error}"))?;
                let at_text = raw_at
                    .as_str()
                    .ok_or("at must be an RFC-3339 timestamp string")?;
                let at = bioprism_scope::Timestamp::parse(at_text)
                    .map_err(|error| format!("invalid at timestamp: {error}"))?;
                match study.check_consent(&consent, at) {
                    Ok(()) => json!({ "status": "admitted", "at": at_text }),
                    Err(error) => json!({
                        "status": "refused",
                        "at": at_text,
                        "refusal": error.to_string(),
                        "fail_closed": true,
                    }),
                }
            }
        };

        let boundary = match arguments.get("boundary") {
            Some(raw) => serde_json::from_value(raw.clone())
                .map_err(|error| format!("invalid research boundary: {error}"))?,
            None => ResearchBoundary::research_only(),
        };
        let return_of_results = match study.check_return_of_results(&boundary) {
            Ok(()) => json!({ "status": "admitted" }),
            Err(error) => json!({
                "status": "refused",
                "refusal": error.to_string(),
                "fail_closed": true,
            }),
        };

        Ok(json!({
            "ok": true,
            "subject": study.subject,
            "determination": determination,
            "requires_institutional_review": determination.requires_review(),
            "triggers": determination.triggers(),
            "consent": consent_check,
            "return_of_results": return_of_results,
            "clearance_issued": false,
            "guarantees": [
                "no-engagement screening is undetermined, never an exemption",
                "consent is checked against the policy crate's closed purpose vocabulary",
                "individual findings remain subject to the research-only boundary",
            ],
        }))
    }

    fn bioethics_dual_use_review(&self, arguments: &Value) -> Result<Value, String> {
        let raw_release = arguments
            .get("release")
            .cloned()
            .ok_or("release is required and must be a serialized CapabilityRelease")?;
        let release: CapabilityRelease = serde_json::from_value(raw_release)
            .map_err(|error| format!("invalid capability release: {error}"))?;
        let raw_risk = arguments
            .get("risk")
            .cloned()
            .ok_or("risk is required and must be a serialized RiskAssessment")?;
        let risk: RiskAssessment = serde_json::from_value(raw_risk)
            .map_err(|error| format!("invalid risk assessment: {error}"))?;

        let referral = match refer_dual_use(&release, &risk) {
            Ok(referral) => referral,
            Err(error) => {
                return Ok(json!({
                    "ok": false,
                    "stage": "dual_use_release",
                    "refusal": error.to_string(),
                    "fail_closed": true,
                    "guarantee": "unassessed misuse, subject mismatch, missing category, or unrated safety dimensions do not release"
                }))
            }
        };

        let withholding = match arguments.get("withhold") {
            None => json!({ "status": "not_requested" }),
            Some(raw) => {
                let scope: bioprism_safety::release::WithholdScope =
                    serde_json::from_value(raw.clone())
                        .map_err(|error| format!("invalid withhold scope: {error}"))?;
                let finding = arguments
                    .get("finding")
                    .and_then(Value::as_str)
                    .unwrap_or("caller-supplied finding");
                match referral.withhold(finding, scope) {
                    Ok(scope) => json!({ "status": "admitted", "scope": scope }),
                    Err(error) => json!({
                        "status": "refused",
                        "scope": scope,
                        "refusal": error.to_string(),
                        "fail_closed": true,
                    }),
                }
            }
        };

        Ok(json!({
            "ok": true,
            "subject": referral.subject(),
            "surfaces": referral.surfaces(),
            "assessor": referral.assessor(),
            "sensitive_category": referral.category(),
            "decision": referral.decision(),
            "referral": referral,
            "withholding": withholding,
            "guarantees": [
                "an assessed empty surface set is distinct from no assessment",
                "the section 13 risk gate is reused without a second dual-use rule",
                "suppressing exploit detail remains distinct from suppressing the existence of a finding",
            ],
        }))
    }

    fn bioethics_validation_check(&self, arguments: &Value) -> Result<Value, String> {
        let raw_dossier = arguments
            .get("dossier")
            .cloned()
            .ok_or("dossier is required and must be a serialized ValidationDossier")?;
        let raw_bytes = serde_json::to_vec(&raw_dossier).map_err(|error| error.to_string())?;
        if raw_bytes.len() > 10_000_000 {
            return Err("validation dossier exceeds the 10000000-byte safety bound".into());
        }
        let dossier: ValidationDossier = serde_json::from_value(raw_dossier)
            .map_err(|error| format!("invalid validation dossier: {error}"))?;
        let missing = dossier.missing();
        let verification = match dossier.verify() {
            Ok(verified) => json!({
                "status": "verified",
                "verified_module": verified,
            }),
            Err(error) => json!({
                "status": "refused",
                "refusal": error.to_string(),
                "fail_closed": true,
            }),
        };
        Ok(json!({
            "ok": true,
            "subject": dossier.subject,
            "author": dossier.author,
            "maturity": dossier.maturity(),
            "missing": missing,
            "missing_count": missing.len(),
            "verification": verification,
            "guarantees": [
                "blank or absent evidence is not treated as satisfied",
                "independent reproduction must name an actor other than the author",
                "verified status is minted only by the in-process validation check",
            ],
        }))
    }

    fn bioethics_representation_audit(&self, arguments: &Value) -> Result<Value, String> {
        let subject = arguments
            .get("subject")
            .and_then(Value::as_str)
            .ok_or("subject is required")?;
        let raw_observations = arguments
            .get("observations")
            .and_then(Value::as_array)
            .ok_or("observations is required and must be an array")?;
        if raw_observations.len() > 10_000 {
            return Err("observations may contain at most 10000 strata".into());
        }
        let observations = raw_observations
            .iter()
            .enumerate()
            .map(|(index, raw)| {
                serde_json::from_value::<StratumObservation>(raw.clone())
                    .map_err(|error| format!("invalid observation at index {index}: {error}"))
            })
            .collect::<Result<Vec<_>, _>>()?;
        let summary = match summarise(subject, observations) {
            Ok(summary) => summary,
            Err(error) => {
                return Ok(json!({
                    "ok": false,
                    "stage": "representation_partition",
                    "refusal": error.to_string(),
                    "fail_closed": true,
                }))
            }
        };

        let attribution = match arguments.get("attribution") {
            None => json!({ "status": "not_requested" }),
            Some(raw) => {
                let object = raw.as_object().ok_or("attribution must be an object")?;
                let axis: ContextAxis = serde_json::from_value(
                    object
                        .get("axis")
                        .cloned()
                        .ok_or("attribution.axis is required")?,
                )
                .map_err(|error| format!("invalid attribution axis: {error}"))?;
                let raw_matched = object
                    .get("matched")
                    .and_then(Value::as_array)
                    .ok_or("attribution.matched is required and must be an array")?;
                let matched = raw_matched
                    .iter()
                    .cloned()
                    .map(|item| {
                        serde_json::from_value::<ContextAxis>(item)
                            .map_err(|error| format!("invalid matched context axis: {error}"))
                    })
                    .collect::<Result<BTreeSet<_>, _>>()?;
                let finding = object
                    .get("finding")
                    .and_then(Value::as_str)
                    .ok_or("attribution.finding is required")?;
                let decision = attribute_representation(axis, &matched);
                let standing = match decision.clone().require_context(finding) {
                    Ok(axis) => json!({ "status": "admitted", "axis": axis }),
                    Err(error) => json!({
                        "status": "refused",
                        "refusal": error.to_string(),
                        "fail_closed": true,
                    }),
                };
                json!({ "status": "evaluated", "decision": decision, "standing": standing })
            }
        };

        Ok(json!({
            "ok": true,
            "summary": summary,
            "measured_count": summary.measured().len(),
            "unmeasured_count": summary.unmeasured().len(),
            "suppressed_count": summary.suppressed().len(),
            "complete": summary.is_complete(),
            "incomplete_axes": summary.incomplete_axes(),
            "attribution": attribution,
            "guarantees": [
                "measured, unmeasured, and small-cell-suppressed strata remain separate",
                "duplicate strata refuse rather than overwrite one another",
                "resource-context mismatch blocks attribution to a demographic or geographic axis",
            ],
        }))
    }

    fn influence_analyze(&self, arguments: &Value) -> Result<Value, String> {
        let label = arguments
            .get("label")
            .and_then(Value::as_str)
            .ok_or("label is required")?;
        let raw_variables = arguments
            .get("variables")
            .and_then(Value::as_object)
            .ok_or("variables is required and must map variable names to positive cardinalities")?;
        if raw_variables.is_empty() || raw_variables.len() > 10_000 {
            return Err("variables must contain between 1 and 10000 entries".into());
        }
        let assumed = arguments
            .get("assumed_variables")
            .map(|raw| -> Result<BTreeSet<String>, String> {
                let values = raw.as_array().ok_or("assumed_variables must be an array")?;
                let assumed = values
                    .iter()
                    .map(|item| {
                        item.as_str()
                            .map(str::to_string)
                            .ok_or("assumed_variables must contain strings")
                    })
                    .collect::<Result<BTreeSet<_>, _>>()?;
                if assumed.len() != values.len() {
                    return Err("assumed_variables must not contain duplicates".into());
                }
                Ok(assumed)
            })
            .transpose()?;
        let assumed = assumed.unwrap_or_default();
        if let Some(variable) = assumed
            .iter()
            .find(|variable| !raw_variables.contains_key(*variable))
        {
            return Err(format!(
                "assumed_variables names undeclared variable {variable:?}"
            ));
        }
        let mut builder = QueryRegion::builder(label);
        for (name, raw_cardinality) in raw_variables {
            let cardinality = raw_cardinality.as_u64().ok_or_else(|| {
                format!("cardinality for variable {name:?} must be a positive integer")
            })?;
            if cardinality == 0 || cardinality > 1_000_000 {
                return Err(format!(
                    "cardinality for variable {name:?} must be between 1 and 1000000"
                ));
            }
            if assumed.contains(name) {
                builder = builder.assumed_variable(name.clone(), cardinality as usize);
            } else {
                builder = builder.observed_variable(name.clone(), cardinality as usize);
            }
        }

        let raw_factors = arguments
            .get("factors")
            .and_then(Value::as_array)
            .ok_or("factors is required and must be an array")?;
        if raw_factors.is_empty() || raw_factors.len() > 1_000 {
            return Err("factors must contain between 1 and 1000 entries".into());
        }
        for (index, raw_factor) in raw_factors.iter().enumerate() {
            let object = raw_factor
                .as_object()
                .ok_or_else(|| format!("factor at index {index} must be an object"))?;
            let id = object
                .get("id")
                .and_then(Value::as_str)
                .ok_or_else(|| format!("factor at index {index} is missing id"))?;
            let raw_scope = object
                .get("scope")
                .and_then(Value::as_array)
                .ok_or_else(|| format!("factor {id:?} is missing scope"))?;
            if raw_scope.is_empty() || raw_scope.len() > 128 {
                return Err(format!(
                    "factor {id:?} scope must contain between 1 and 128 variables"
                ));
            }
            let scope = raw_scope
                .iter()
                .map(|item| {
                    item.as_str()
                        .map(str::to_string)
                        .ok_or_else(|| format!("factor {id:?} scope must contain strings"))
                })
                .collect::<Result<Vec<_>, _>>()?;
            let factor = match object.get("table") {
                None | Some(Value::Null) => RegionFactor::structural(id, scope),
                Some(raw_table) => {
                    let raw_table = raw_table
                        .as_array()
                        .ok_or_else(|| format!("factor {id:?} table must be an array"))?;
                    if raw_table.len() > 4_194_304 {
                        return Err(format!(
                            "factor {id:?} table exceeds the 4194304-entry safety bound"
                        ));
                    }
                    let table = raw_table
                        .iter()
                        .map(|item| {
                            item.as_f64().ok_or_else(|| {
                                format!("factor {id:?} table must contain finite numbers")
                            })
                        })
                        .collect::<Result<Vec<_>, _>>()?;
                    RegionFactor::with_table(id, scope, table)
                }
            };
            builder = builder.factor(factor);
        }

        let raw_free = arguments
            .get("free")
            .and_then(Value::as_array)
            .ok_or("free is required and must be an array of variable names")?;
        if raw_free.is_empty() || raw_free.len() > raw_variables.len() {
            return Err(
                "free must contain at least one and no more than the declared variables".into(),
            );
        }
        let mut seen_free = BTreeSet::new();
        for item in raw_free {
            let variable = item.as_str().ok_or("free must contain strings")?;
            if !seen_free.insert(variable) {
                return Err(format!(
                    "free must not contain duplicate variable {variable:?}"
                ));
            }
            builder = builder.free(variable);
        }
        let region = builder
            .build()
            .map_err(|error| format!("invalid influence region: {error}"))?;

        let raw_perturbation = arguments
            .get("perturbation")
            .cloned()
            .ok_or("perturbation is required and must name removal or multiplicative_range")?;
        let perturbation: Perturbation = serde_json::from_value(raw_perturbation)
            .map_err(|error| format!("invalid perturbation: {error}"))?;
        let subjects = match (arguments.get("factor"), arguments.get("factor_group")) {
            (Some(_), Some(_)) => return Err("provide factor or factor_group, not both".into()),
            (Some(raw), None) => vec![raw.as_str().ok_or("factor must be a string")?.to_string()],
            (None, Some(raw)) => {
                let values = raw
                    .as_array()
                    .ok_or("factor_group must be an array of factor ids")?;
                if values.is_empty() || values.len() > 1_000 {
                    return Err("factor_group must contain between 1 and 1000 ids".into());
                }
                let group = values
                    .iter()
                    .map(|item| {
                        item.as_str()
                            .map(str::to_string)
                            .ok_or("factor_group must contain strings")
                    })
                    .collect::<Result<Vec<_>, _>>()?;
                if group.iter().collect::<BTreeSet<_>>().len() != group.len() {
                    return Err("factor_group must not contain duplicate factor ids".into());
                }
                group
            }
            (None, None) => return Err("factor or factor_group is required".into()),
        };

        let mut budget = InfluenceBudget::default();
        if let Some(raw_budget) = arguments.get("budget") {
            let object = raw_budget.as_object().ok_or("budget must be an object")?;
            if let Some(value) = object.get("max_induced_width") {
                let width = value
                    .as_u64()
                    .ok_or("budget.max_induced_width must be an integer")?;
                if width > 1024 {
                    return Err("budget.max_induced_width must be at most 1024".into());
                }
                budget = budget.with_max_induced_width(width as usize);
            }
            if let Some(value) = object.get("max_peak_entries") {
                let entries = value
                    .as_f64()
                    .ok_or("budget.max_peak_entries must be a number")?;
                if !entries.is_finite() || entries <= 0.0 {
                    return Err("budget.max_peak_entries must be a finite positive number".into());
                }
                budget = budget.with_max_peak_entries(entries);
            }
            if let Some(value) = object.get("max_ops") {
                let ops = value.as_f64().ok_or("budget.max_ops must be a number")?;
                if !ops.is_finite() || ops <= 0.0 {
                    return Err("budget.max_ops must be a finite positive number".into());
                }
                budget = budget.with_max_ops(ops);
            }
        }
        let execute = arguments
            .get("execute")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let analyzer = InfluenceAnalyzer::new(budget);
        let analyzer = if execute {
            analyzer
        } else {
            analyzer.structural_only()
        };
        let analysis = if subjects.len() == 1 {
            analyzer
                .analyse_factor(&region, &subjects[0], &perturbation)
                .map_err(|error| error.to_string())?
        } else {
            analyzer
                .analyse_group(&region, &subjects, &perturbation)
                .map_err(|error| error.to_string())?
        };
        let factor_summary = region
            .factors()
            .iter()
            .map(|factor| {
                json!({
                    "id": factor.id(),
                    "scope": factor.scope(),
                    "arity": factor.arity(),
                    "has_table": factor.table().is_some(),
                })
            })
            .collect::<Vec<_>>();
        Ok(json!({
            "ok": true,
            "region": {
                "label": region.label(),
                "variables": region.cardinality(),
                "free": region.free_variables(),
                "bound": region.bound_variables(),
                "factors": factor_summary,
                "has_tables": region.has_tables(),
                "joint_entries": region.joint_entries(),
                "free_entries": region.free_entries(),
                "assumed_cardinality_fraction": region.assumed_cardinality_fraction(),
            },
            "subjects": subjects,
            "perturbation": perturbation,
            "execute": execute,
            "analysis": analysis,
            "looseness": analysis.looseness(),
            "guarantees": [
                "unknown influence remains an InfluenceEstimate::Unknown rather than a numeric infinity",
                "the default is structural-only and does not execute a query",
                "every reported bound carries its metric, method, approximation direction, and validity scope",
            ],
        }))
    }

    fn routing_decide(&self, arguments: &Value) -> Result<Value, String> {
        let raw_fingerprint = arguments
            .get("fingerprint")
            .cloned()
            .ok_or("fingerprint is required and must be a serialized Fingerprint")?;
        let fingerprint: Fingerprint = serde_json::from_value(raw_fingerprint)
            .map_err(|error| format!("invalid routing fingerprint: {error}"))?;

        let raw_evidence = arguments
            .get("evidence")
            .cloned()
            .ok_or("evidence is required and must be an array of observations")?;
        let evidence_items = raw_evidence
            .as_array()
            .ok_or("evidence must be an array of serialized observations")?;
        if evidence_items.len() > 20_000 {
            return Err("evidence may contain at most 20000 observations".into());
        }
        let evidence: EvidenceLedger = serde_json::from_value(raw_evidence)
            .map_err(|error| format!("invalid routing evidence ledger: {error}"))?;

        let raw_policy = arguments
            .get("policy")
            .cloned()
            .ok_or("policy is required and must be a serialized RoutingPolicy")?;
        let policy: RoutingPolicy = serde_json::from_value(raw_policy)
            .map_err(|error| format!("invalid routing policy: {error}"))?;
        policy
            .validate()
            .map_err(|error| format!("routing policy is invalid: {error}"))?;

        let task_id = arguments.get("task_id").and_then(Value::as_str);
        if arguments.get("task_id").is_some() && task_id.is_none() {
            return Err("task_id must be a string when supplied".into());
        }
        if task_id.is_some_and(str::is_empty) {
            return Err("task_id must not be empty".into());
        }
        let decision = match task_id {
            Some(task_id) => policy
                .route_unseen(task_id, &fingerprint, &evidence)
                .map_err(|error| format!("routing refused: {error}"))?,
            None => policy
                .route(&fingerprint, &evidence)
                .map_err(|error| format!("routing refused: {error}"))?,
        };
        let neighbourhood = evidence
            .neighbourhood(&fingerprint, policy.neighbourhood_radius)
            .len();

        Ok(json!({
            "ok": true,
            "decision": decision,
            "task_id": task_id,
            "holdout_check": if task_id.is_some() { "enforced" } else { "caller_must_supply_unseen_identity" },
            "evidence": {
                "observations": evidence.len(),
                "distinct_tasks": evidence.task_ids().len(),
                "neighbourhood_observations": neighbourhood,
                "neighbourhood_radius": policy.neighbourhood_radius,
            },
            "guarantees": [
                "the policy can select only from its approved architecture set",
                "insufficient coverage or margin abstains to the declared safe default",
                "route_unseen refuses evidence containing the routed task identity",
                "confidence is a routing score, not a posterior probability",
            ],
        }))
    }

    fn routing_lab_run(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments)
            .map_err(|error| format!("cannot measure routing-lab input: {error}"))?;
        if encoded.len() > 20_000_000 {
            return Err("routing-lab input exceeds the 20000000-byte safety bound".into());
        }
        let raw_tasks = arguments
            .get("tasks")
            .and_then(Value::as_array)
            .ok_or("tasks is required and must be an array of {task_id, world, query} objects")?;
        if raw_tasks.is_empty() || raw_tasks.len() > 256 {
            return Err("tasks must contain between 1 and 256 task objects".into());
        }
        let mut tasks = Vec::with_capacity(raw_tasks.len());
        for (index, raw_task) in raw_tasks.iter().enumerate() {
            let object = raw_task
                .as_object()
                .ok_or_else(|| format!("tasks[{index}] must be an object"))?;
            let task_id = object
                .get("task_id")
                .and_then(Value::as_str)
                .ok_or_else(|| format!("tasks[{index}].task_id must be a string"))?;
            if task_id.is_empty() || task_id.len() > 512 {
                return Err(format!(
                    "tasks[{index}].task_id must contain between 1 and 512 bytes"
                ));
            }
            let raw_world = object
                .get("world")
                .cloned()
                .ok_or_else(|| format!("tasks[{index}].world is required"))?;
            let world = World::from_json(raw_world)
                .map_err(|error| format!("tasks[{index}].world is invalid: {error}"))?;
            let raw_query = object
                .get("query")
                .cloned()
                .ok_or_else(|| format!("tasks[{index}].query is required"))?;
            let query = Query::from_json(raw_query)
                .map_err(|error| format!("tasks[{index}].query is invalid: {error}"))?;
            let task = Task::new(task_id, world, query)
                .map_err(|error| format!("tasks[{index}] is invalid: {error}"))?;
            tasks.push(task);
        }

        let raw_settings = arguments
            .get("settings")
            .cloned()
            .ok_or("settings is required and must be a serialized LabSettings")?;
        let settings: LabSettings = serde_json::from_value(raw_settings)
            .map_err(|error| format!("invalid routing-lab settings: {error}"))?;
        if settings.calibration_bins == 0 || settings.calibration_bins > 100 {
            return Err("settings.calibration_bins must be between 1 and 100".into());
        }
        let include_rows = arguments
            .get("include_rows")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let max_rows = arguments
            .get("max_rows")
            .and_then(Value::as_u64)
            .unwrap_or(100);
        if max_rows == 0 || max_rows > 1_000 {
            return Err("max_rows must be between 1 and 1000".into());
        }

        let report = match run_routing_lab(&tasks, &settings) {
            Ok(report) => report,
            Err(error) => {
                return Ok(json!({
                    "ok": false,
                    "schema": "bioprism-mcp/routing-lab-run/0.1",
                    "stage": "lab_execution",
                    "refusal": error.to_string(),
                    "fail_closed": true,
                    "guarantees": [
                        "a routing report is not emitted when an architecture outcome is unjudged or holdout evidence cannot be constructed",
                        "partial comparator rows are not promoted to a complete regret account",
                    ],
                }));
            }
        };
        let task_rows = if include_rows {
            serde_json::to_value(
                report
                    .tasks
                    .iter()
                    .take(max_rows as usize)
                    .collect::<Vec<_>>(),
            )
            .map_err(|error| format!("cannot serialize routing-lab task rows: {error}"))?
        } else {
            json!([])
        };
        let account = serde_json::to_value(&report.account)
            .map_err(|error| format!("cannot serialize routing-lab regret account: {error}"))?;
        let calibration = serde_json::to_value(&report.calibration)
            .map_err(|error| format!("cannot serialize routing-lab calibration: {error}"))?;
        let verdict = serde_json::to_value(report.verdict)
            .map_err(|error| format!("cannot serialize routing-lab verdict: {error}"))?;
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/routing-lab-run/0.1",
            "tasks": tasks.len(),
            "holdout": settings.holdout,
            "holdout_label": settings.holdout.as_str(),
            "approved_architectures": settings.policy.approved.iter().map(|architecture| architecture.label()).collect::<Vec<_>>(),
            "fixed_default": settings.fixed_default,
            "include_rows": include_rows,
            "report": {
                "account": account,
                "calibration": calibration,
                "verdict": verdict,
                "abstention_rate": report.abstention_rate,
                "oracle_agreement_rate": report.oracle_agreement_rate,
                "tasks_won": report.tasks_won,
                "tasks_lost": report.tasks_lost,
                "tasks_tied": report.tasks_tied,
                "caveats": report.caveats,
                "task_rows": task_rows,
                "task_rows_omitted": if include_rows { report.tasks.len().saturating_sub(max_rows as usize) } else { report.tasks.len() },
            },
            "guarantees": [
                "the full approved architecture panel is observed before routing, so the oracle comparator remains retrospective and labelled",
                "each routed task is evaluated through route_unseen against task- or regime-restricted evidence",
                "fixed-default, most-expensive-default, router, and oracle outcomes remain separate",
                "captured gain, regret, abstention, and calibration remain report fields rather than a single flattering win rate",
            ],
            "limitations": [
                "this is an offline context-architecture lab; it does not select models, prompts, providers, or production agent topologies",
                "worlds and queries are caller-supplied and the lab performs no network, filesystem, model, or patient-facing action",
                "the oracle retrospective selector is a ceiling, not a deployable policy, and confidence is not a posterior probability",
            ],
        }))
    }

    fn token_context_plan(&self, arguments: &Value) -> Result<Value, String> {
        let raw_request = arguments
            .get("request")
            .cloned()
            .ok_or("request is required and must be a serialized ContextRequest")?;
        let request: ContextRequest = serde_json::from_value(raw_request)
            .map_err(|error| format!("invalid token context request: {error}"))?;
        if request.envelope.total > 10_000_000 {
            return Err("request.envelope.total must be at most 10000000".into());
        }

        let parse_candidates = |name: &str| -> Result<Vec<PlanCandidate>, String> {
            let raw = arguments
                .get(name)
                .cloned()
                .ok_or_else(|| format!("{name} is required and must be an array"))?;
            let items = raw
                .as_array()
                .ok_or_else(|| format!("{name} must be an array"))?;
            if items.is_empty() || items.len() > 10_000 {
                return Err(format!(
                    "{name} must contain between 1 and 10000 candidates"
                ));
            }
            let candidates: Vec<PlanCandidate> =
                serde_json::from_value(raw).map_err(|error| format!("invalid {name}: {error}"))?;
            let mut seen = BTreeSet::new();
            for candidate in &candidates {
                if candidate.node_id.is_empty() {
                    return Err(format!("{name} contains a candidate with an empty node_id"));
                }
                if candidate.estimate.tokens > 10_000_000 {
                    return Err(format!(
                        "candidate {:?} exceeds the 10000000-token safety bound",
                        candidate.node_id
                    ));
                }
                if !seen.insert(candidate.node_id.as_str()) {
                    return Err(format!(
                        "{name} contains duplicate node_id {:?}",
                        candidate.node_id
                    ));
                }
            }
            Ok(candidates)
        };

        let candidates = parse_candidates("candidates")?;
        let base_plan = plan_token_context(&request, &candidates)
            .map_err(|error| format!("token planning refused: {error}"))?;

        let has_variant_request = arguments.get("variant_request").is_some();
        let has_variant_candidates = arguments.get("variant_candidates").is_some();
        if has_variant_request != has_variant_candidates {
            return Err(
                "variant_request and variant_candidates must be supplied together for comparison"
                    .into(),
            );
        }
        let comparison = if has_variant_request {
            let variant_request: ContextRequest = serde_json::from_value(
                arguments
                    .get("variant_request")
                    .cloned()
                    .expect("variant request was checked above"),
            )
            .map_err(|error| format!("invalid variant token context request: {error}"))?;
            if variant_request.envelope.total > 10_000_000 {
                return Err("variant_request.envelope.total must be at most 10000000".into());
            }
            let variant_candidates = parse_candidates("variant_candidates")?;
            Some(
                compare_token_plans(
                    "mcp-token-policy-comparison",
                    &request,
                    &variant_request,
                    &candidates,
                    &variant_candidates,
                )
                .map_err(|error| format!("token comparison refused: {error}"))?,
            )
        } else {
            None
        };

        Ok(json!({
            "ok": true,
            "plan": base_plan,
            "comparison": comparison,
            "guarantees": [
                "dry_run refuses before touching any candidate marked restricted",
                "the mandatory closure is checked before a plan is returned",
                "candidate ids are unique and stable at the transport boundary",
                "policy comparisons are admitted only when request fields other than policy match",
                "token counts retain their estimation method and are never presented as measured by this server",
            ],
        }))
    }

    fn weavelang_compile(&self, arguments: &Value) -> Result<Value, String> {
        let source = arguments
            .get("source")
            .and_then(Value::as_str)
            .ok_or("source is required and must be WeaveLang text")?;
        if source.is_empty() {
            return Err("source must not be empty".into());
        }
        if source.len() > 2_000_000 {
            return Err("source exceeds the 2000000-byte safety bound".into());
        }
        let execute = arguments
            .get("execute")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let mode_text = arguments
            .get("mode")
            .and_then(Value::as_str)
            .unwrap_or("replay");
        let mode: ExecutionMode = serde_json::from_value(json!(mode_text))
            .map_err(|error| format!("mode must be replay or live: {error}"))?;
        let thread_id = arguments
            .get("thread_id")
            .and_then(Value::as_str)
            .unwrap_or("mcp-weavelang");
        if thread_id.is_empty() || thread_id.len() > 256 {
            return Err("thread_id must contain between 1 and 256 bytes".into());
        }
        let include_ir = arguments
            .get("include_ir")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let include_trace = arguments
            .get("include_trace")
            .and_then(Value::as_bool)
            .unwrap_or(false);

        let ir = compile_weave(source)
            .map_err(|error| format!("WeaveLang compilation refused: {error}"))?;
        let digest = ir.digest().map_err(|error| error.to_string())?;
        let semantic_digest = ir.semantic_digest().map_err(|error| error.to_string())?;
        let mut machine = Machine::load(ir.clone(), mode, thread_id);
        let initial_state = machine.state().to_string();
        let initial_invariants = machine.check_invariants();
        let initial_liveness = machine.liveness();
        let execution = if execute {
            match machine.run() {
                Ok(trace) => json!({
                    "status": "completed",
                    "mode": mode,
                    "state": machine.state(),
                    "event_count": trace.events.len(),
                    "trace_digest": trace.digest,
                    "trace": include_trace.then_some(trace),
                    "liveness": machine.liveness(),
                    "invariant_violations": machine.check_invariants(),
                }),
                Err(error) => json!({
                    "status": "refused",
                    "mode": mode,
                    "error": error.to_string(),
                    "fail_closed": true,
                    "state": machine.state(),
                    "liveness": machine.liveness(),
                    "invariant_violations": machine.check_invariants(),
                }),
            }
        } else {
            json!({
                "status": "not_requested",
                "mode": mode,
                "state": initial_state,
                "liveness": initial_liveness,
                "invariant_violations": initial_invariants,
            })
        };

        Ok(json!({
            "ok": true,
            "program": {
                "program_id": ir.program_id.clone(),
                "digest": digest,
                "semantic_digest": semantic_digest,
                "weave_ir_version": ir.weave_ir_version.clone(),
                "roles": ir.roles.len(),
                "participants": ir.participants.len(),
                "interfaces": ir.interfaces.len(),
                "policies": ir.policies.len(),
                "state_nodes": ir.state_graph.nodes.len(),
                "transitions": ir.state_graph.transitions.len(),
                "monitors": ir.monitors.len(),
                "initial_state": ir.choreography.initial_state.clone(),
                "terminal_states": ir.choreography.terminal_states.clone(),
            },
            "execution": execution,
            "ir": include_ir.then_some(ir),
            "guarantees": [
                "compilation is deterministic and returns both whole-document and semantic digests",
                "replay is the default execution mode and refuses world-mutating transitions",
                "execution is a local semantic trace; it performs no network, model, or tool call",
                "unimplemented language phases remain visible as compiler limitations rather than inferred capabilities",
            ],
        }))
    }

    fn choreography_check(&self, arguments: &Value) -> Result<Value, String> {
        let raw_global = arguments
            .get("global")
            .cloned()
            .ok_or("global is required and must be a serialized GlobalType")?;
        let encoded = serde_json::to_vec(&raw_global).map_err(|error| error.to_string())?;
        if encoded.len() > 2_000_000 {
            return Err("global choreography exceeds the 2000000-byte safety bound".into());
        }
        let global: GlobalType = serde_json::from_value(raw_global)
            .map_err(|error| format!("invalid global choreography: {error}"))?;
        let bound: ExplorationBound = match arguments.get("bound") {
            None => ExplorationBound::default(),
            Some(raw) => serde_json::from_value(raw.clone())
                .map_err(|error| format!("invalid exploration bound: {error}"))?,
        };
        if bound.max_states == 0
            || bound.max_states > 100_000
            || bound.max_depth == 0
            || bound.max_depth > 10_000
            || bound.channel_capacity > 64
        {
            return Err(
                "bound must use 1..=100000 states, 1..=10000 depth, and at most 64 queued messages"
                    .into(),
            );
        }
        let roles = global
            .roles()
            .into_iter()
            .map(|role| role.to_string())
            .collect::<Vec<_>>();
        let checked = match WellFormedGlobal::check(global) {
            Ok(checked) => checked,
            Err(error) => {
                return Ok(json!({
                    "ok": true,
                    "well_formed": false,
                    "roles": roles,
                    "refusal": error.to_string(),
                    "protocol_error": error,
                    "fail_closed": true,
                    "guarantees": [
                        "an ill-formed global type yields no local projections",
                        "projection failures are returned before model checking",
                        "no protocol repair is inferred or silently applied",
                    ],
                }))
            }
        };
        let digest = checked.digest().map_err(|error| error.to_string())?;
        let system = ChoreographySystem::from_projection(&checked);
        let report = system.check(bound);

        Ok(json!({
            "ok": true,
            "well_formed": true,
            "digest": digest,
            "roles": roles,
            "projection_count": checked.projections().len(),
            "bound": bound,
            "model_check": report,
            "all_proved": report.all_proved(),
            "omissions": report.omissions(),
            "guarantees": [
                "well-formedness is established by projecting every named role",
                "deadlock, liveness, orphan, and unexpected-message verdicts preserve holds, fails, and inconclusive states",
                "a bounded search is never presented as universal proof when it hit a bound",
                "model checking is local and performs no network or participant execution",
            ],
        }))
    }

    fn conformance_run(&self, arguments: &Value) -> Result<Value, String> {
        let include_details = arguments
            .get("include_details")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let max_items = arguments
            .get("max_items")
            .and_then(Value::as_u64)
            .unwrap_or(100);
        if !(1..=1_000).contains(&max_items) {
            return Err("max_items must be between 1 and 1000".into());
        }

        let suite = fiber_suite();
        let fixtures = FixtureStore::load(workspace_fixture_root(), &suite.manifest)
            .map_err(|error| format!("conformance fixture load refused: {error}"))?;
        fixtures
            .verify()
            .map_err(|error| format!("conformance fixture verification refused: {error}"))?;
        let report = suite
            .run(&FiberReference, &fixtures)
            .map_err(|error| format!("conformance run refused: {error}"))?
            .declaring_baseline(shipped_baseline());
        let decision = assess_conformance(&report);
        let results = if include_details {
            Some(
                report
                    .results
                    .iter()
                    .take(max_items as usize)
                    .collect::<Vec<_>>(),
            )
        } else {
            None
        };
        Ok(json!({
            "ok": true,
            "suite": {
                "id": report.suite_id.clone(),
                "version": report.suite_version.clone(),
                "digest": report.suite_digest.clone(),
                "fixture_manifest_id": report.fixture_manifest_id.clone(),
                "fixture_count": report.fixture_count,
                "synthetic_fixture_count": report.synthetic_fixtures.len(),
                "case_count": report.results.len(),
                "passed": report.passed(),
                "failed": report.failed(),
                "unsupported": report.unsupported(),
                "errored": report.errored(),
                "fixture_drift": report.fixture_drift.clone(),
                "pyramid": report.pyramid(),
                "fully_conformant": report.is_fully_conformant(),
            },
            "release_decision": decision,
            "summary": report.summary(),
            "results": results,
            "guarantees": [
                "fixture digests are verified before any case result is trusted",
                "required failures, unsupported artifacts, and fixture drift remain distinct",
                "the equal-engineering baseline is declared in the report and is not silently invented",
                "a conformance run is evidence for release review, not an assertion of clinical or production readiness",
            ],
        }))
    }

    fn provider_capability_gate(&self, arguments: &Value) -> Result<Value, String> {
        let raw_card = arguments
            .get("card")
            .cloned()
            .ok_or("card is required and must be a serialized CapabilityCard")?;
        let card_bytes = serde_json::to_vec(&raw_card).map_err(|error| error.to_string())?;
        if card_bytes.len() > 5_000_000 {
            return Err("capability card exceeds the 5000000-byte safety bound".into());
        }
        let card: SweepCapabilityCard = serde_json::from_value(raw_card)
            .map_err(|error| format!("invalid provider capability card: {error}"))?;
        let raw_required = arguments
            .get("required")
            .cloned()
            .ok_or("required is required and must contain capability check names")?;
        let required_items = raw_required.as_array().ok_or("required must be an array")?;
        if required_items.is_empty() || required_items.len() > 17 {
            return Err("required must contain between 1 and 17 checks".into());
        }
        let required: Vec<SweepCheck> = serde_json::from_value(raw_required)
            .map_err(|error| format!("invalid required capability checks: {error}"))?;
        if required.iter().any(|check| !check.is_pass_fail()) {
            return Err(
                "performance checks are measurements and cannot be used as pass/fail requirements"
                    .into(),
            );
        }
        let include_card = arguments
            .get("include_card")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let differential = match arguments.get("other_card") {
            None => None,
            Some(raw_other) => {
                let other: SweepCapabilityCard = serde_json::from_value(raw_other.clone())
                    .map_err(|error| format!("invalid other provider capability card: {error}"))?;
                Some(sweep_differential(&card, &other))
            }
        };
        let required_states = required
            .iter()
            .map(|check| (format!("{check:?}"), json!(card.state(*check))))
            .collect::<serde_json::Map<String, Value>>();
        let gate = sweep_gate(&card, &required);

        Ok(json!({
            "ok": true,
            "provider": serde_json::to_value(&card)
                .ok()
                .and_then(|value| value.get("provider").cloned()),
            "required": required,
            "required_states": required_states,
            "gate": gate,
            "claims": card.claims(),
            "measurement_count": card.measurements().len(),
            "differential": differential,
            "card": include_card.then_some(card),
            "guarantees": [
                "untested and failed capabilities both block a required claim",
                "performance measurements cannot be turned into pass/fail claims without an authorized threshold",
                "a differential with an untested side remains indeterminate, not agreement",
                "the gate reports provider evidence and does not execute runtime tests",
            ],
        }))
    }

    fn sdk_registry_check(&self, arguments: &Value) -> Result<Value, String> {
        let raw_manifests = arguments
            .get("manifests")
            .and_then(Value::as_array)
            .ok_or("manifests is required and must be an array of PluginManifest values")?;
        if raw_manifests.is_empty() || raw_manifests.len() > 256 {
            return Err("manifests must contain between 1 and 256 entries".into());
        }
        let encoded = serde_json::to_vec(&json!({
            "manifests": raw_manifests,
            "policy": arguments.get("policy"),
        }))
        .map_err(|error| format!("cannot measure SDK registry envelope: {error}"))?;
        if encoded.len() > 20_000_000 {
            return Err("SDK registry input exceeds the 20000000-byte safety bound".into());
        }
        let policy = arguments
            .get("policy")
            .cloned()
            .map(serde_json::from_value::<SdkRegistryPolicy>)
            .transpose()
            .map_err(|error| format!("invalid registry policy: {error}"))?
            .unwrap_or_default();

        let mut manifests = Vec::with_capacity(raw_manifests.len());
        let mut rows = Vec::with_capacity(raw_manifests.len());
        let mut invalid = false;
        for (index, raw) in raw_manifests.iter().enumerate() {
            let manifest: PluginManifest = match serde_json::from_value(raw.clone()) {
                Ok(manifest) => manifest,
                Err(error) => {
                    invalid = true;
                    rows.push(json!({
                        "index": index,
                        "valid": false,
                        "refusal": format!("invalid plugin manifest: {error}"),
                    }));
                    continue;
                }
            };
            let validation = manifest.validate();
            let digest = manifest.digest().ok().map(|value| value.to_string());
            let core_digest = manifest.core_digest().ok().map(|value| value.to_string());
            let trust = manifest.trust().ok();
            if validation.is_err() {
                invalid = true;
            }
            rows.push(json!({
                "index": index,
                "id": manifest.id(),
                "valid": validation.is_ok(),
                "validation_error": validation.as_ref().err().map(ToString::to_string),
                "digest": digest,
                "core_digest": core_digest,
                "capability_kinds": manifest.capability_kinds().into_iter().map(|kind| format!("{kind:?}")).collect::<Vec<_>>(),
                "trust": trust,
            }));
            if validation.is_ok() {
                manifests.push(manifest);
            }
        }
        if invalid {
            return Ok(json!({
                "ok": false,
                "stage": "manifest_validation",
                "manifests": rows,
                "registry": Value::Null,
                "fail_closed": true,
                "guarantees": [
                    "registration never repairs or infers a malformed manifest",
                    "digest and trust metadata are diagnostic claims, not behavioural verification",
                    "no partial registry is returned when one manifest is invalid",
                ],
            }));
        }

        let registry = match PluginRegistry::from_manifests(policy, manifests) {
            Ok(registry) => registry,
            Err(error) => {
                return Ok(json!({
                    "ok": false,
                    "stage": "registry_registration",
                    "manifests": rows,
                    "registry": Value::Null,
                    "refusal": error.to_string(),
                    "fail_closed": true,
                    "guarantees": [
                        "schema negotiation, effect policy, duplicate identities, and capability conflicts remain refusals",
                        "registration order is normalized before conflict reporting",
                        "a refused set is never projected as a resolved capability map",
                    ],
                }))
            }
        };
        let resolution = registry
            .resolution()
            .into_iter()
            .map(|(kind, plugin)| (format!("{kind:?}"), json!(plugin)))
            .collect::<BTreeMap<_, _>>();
        let registrations = registry
            .registrations()
            .map(|registration| {
                json!({
                    "id": registration.id(),
                    "digest": registration.digest,
                    "core_digest": registration.core_digest,
                    "negotiated": registration.negotiated,
                    "trust": registration.trust,
                    "load_bearing_selectable": registration.is_selectable_for_load_bearing(registry.policy().load_bearing_floor),
                })
            })
            .collect::<Vec<_>>();
        Ok(json!({
            "ok": true,
            "manifest_count": rows.len(),
            "manifests": rows,
            "registry": {
                "registration_count": registry.len(),
                "resolution": resolution,
                "registrations": registrations,
                "policy": registry.policy(),
            },
            "conformance_note": conformance_note(),
            "guarantees": [
                "manifest declarations are validated before registry admission",
                "resolved capabilities are deterministic only after the full set registers cleanly",
                "trust and load-bearing selection remain separate from registration success",
                "no dynamic loading, signature verification, isolation, network access, or conformance execution is implied",
            ],
        }))
    }

    fn governance_schema_check(&self, arguments: &Value) -> Result<Value, String> {
        let requested = arguments.get("schema").and_then(Value::as_str);
        if arguments.get("schema").is_some() && requested.is_none() {
            return Err("schema must be a schema id string".into());
        }
        let document_relative = arguments.get("document").and_then(Value::as_str);
        let document = match document_relative {
            None => None,
            Some(relative) => {
                let path = self.resolve(relative)?;
                if path.is_dir() {
                    return Err(
                        "governance_schema_check requires a JSON document, not a directory".into(),
                    );
                }
                Some((relative, self.read_json(&path)?))
            }
        };
        let descriptors = known_schemas::all();
        let descriptor_json = |descriptor: &bioprism_governance::SchemaDescriptor| {
            json!({
                "id": descriptor.id,
                "mode": descriptor.mode,
                "field_count": descriptor.fields().len(),
                "fields": descriptor.fields(),
                "paths": descriptor.paths(),
                "hashed_paths": descriptor.hashed_paths(),
            })
        };

        if document.is_none() {
            let selected = descriptors
                .iter()
                .filter(|descriptor| requested.is_none_or(|id| descriptor.id.to_string() == id))
                .map(descriptor_json)
                .collect::<Vec<_>>();
            if selected.is_empty() {
                return Err(format!(
                    "unknown schema {:?}; known schemas are {:?}",
                    requested.unwrap_or(""),
                    descriptors
                        .iter()
                        .map(|descriptor| descriptor.id.to_string())
                        .collect::<Vec<_>>()
                ));
            }
            return Ok(json!({
                "ok": true,
                "mode": "catalog",
                "schema_count": selected.len(),
                "schemas": selected,
                "unknown_fields_are_checked_by_declared_mode": true,
            }));
        }

        let (document_relative, document) = document.expect("document was checked above");
        let selected_id = requested.map(str::to_string).or_else(|| {
            document
                .get("schema_version")
                .and_then(Value::as_str)
                .map(str::to_string)
        });
        let selected_id =
            selected_id.ok_or("schema is required when the document has no schema_version")?;
        let descriptor = descriptors
            .iter()
            .find(|descriptor| descriptor.id.to_string() == selected_id)
            .ok_or_else(|| {
                format!(
                    "unknown schema {selected_id:?}; known schemas are {:?}",
                    descriptors
                        .iter()
                        .map(|descriptor| descriptor.id.to_string())
                        .collect::<Vec<_>>()
                )
            })?;
        let check = descriptor.check_document(&document);
        let metadata = descriptor_json(descriptor);
        Ok(json!({
            "ok": true,
            "mode": "document",
            "document": document_relative,
            "schema": metadata,
            "check": check,
            "conforms": check.conforms(),
            "is_clean": check.is_clean(),
            "unknown_fields_are_not_conformance_failures": true,
        }))
    }

    fn developer_platform_status(&self, arguments: &Value) -> Result<Value, String> {
        let include_details = arguments
            .get("include_details")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let max_items = arguments
            .get("max_items")
            .and_then(Value::as_u64)
            .unwrap_or(100);
        if max_items == 0 || max_items > 1_000 {
            return Err("max_items must be between 1 and 1000".into());
        }
        let max_items = max_items as usize;
        let walkthroughs = standard_walkthroughs().map_err(|error| error.to_string())?;
        let devplat = DevPlatReport::of(&walkthroughs).map_err(|error| error.to_string())?;
        let cookbook = standard_cookbook().map_err(|error| error.to_string())?;
        let workspace =
            CookbookWorkspace::open(self.root.clone()).map_err(|error| error.to_string())?;
        let verification = cookbook.verify(&workspace);
        let lint = lint_catalogue();
        let exit_audit = devx_audit();
        let contract = workspace_contract();
        let defects = verification.defects();
        let surface_summary = contract
            .iter()
            .take(max_items)
            .map(|surface| {
                json!({
                    "id": surface.id,
                    "owns_count": surface.owns.len(),
                    "invalidates_count": surface.invalidates.len(),
                    "rationale": surface.rationale,
                })
            })
            .collect::<Vec<_>>();
        let mut result = json!({
            "ok": true,
            "root": self.root,
            "detail_mode": if include_details { "full" } else { "summary" },
            "max_items": max_items,
            "devplat": {
                "digest": &devplat.digest,
                "verdict_counts": devplat.verdict_counts,
                "modules_classified": devplat.modules_classified(),
                "implemented_count": devplat.implemented.len(),
                "not_implemented_count": devplat.not_implemented.len(),
                "foreign_subject_count": devplat.foreign_subjects.len(),
                "walkthrough_count": devplat.walkthroughs.len(),
                "guarded_claims": devplat.guarded_claims,
                "unguarded_claims": devplat.unguarded_claims,
            },
            "walkthroughs": walkthroughs.iter().map(|walkthrough| json!({
                "id": walkthrough.id(),
                "goal": walkthrough.goal(),
                "standing": walkthrough.standing(),
                "standing_text": walkthrough.standing().as_str(),
                "steps": walkthrough.steps().len(),
                "claims": walkthrough.claims().len(),
                "guarded_claims": walkthrough.standing().guarded_claims(),
                "unguarded_claims": walkthrough.standing().unguarded_claims(),
                "documents_absent_artifact": walkthrough.documents_absent_artifact(),
                "refuted_claims": walkthrough.refuted_claims().len(),
                "narration_permille": walkthrough.narration_permille(),
            })).collect::<Vec<_>>(),
            "cookbook": {
                "recipes": cookbook.recipes().len(),
                "anti_recipes": cookbook.anti_recipes().len(),
                "crates": cookbook.crates(),
                "enforcing_tests": cookbook.enforcing_tests().len(),
                "quotes": cookbook.quotes().len(),
                "verification": {
                    "clean": verification.is_clean(),
                    "crates_checked": verification.crates.len(),
                    "entry_points_checked": verification.entry_points.len(),
                    "tests_checked": verification.tests.len(),
                    "quotes_checked": verification.quotes.len(),
                    "defect_count": defects.len(),
                    "defects_returned": defects.iter().take(max_items).collect::<Vec<_>>(),
                    "omitted_defects": defects.len().saturating_sub(max_items),
                },
            },
            "developer_contract": {
                "surface_count": contract.len(),
                "surfaces_returned": surface_summary,
                "omitted_surfaces": contract.len().saturating_sub(max_items),
            },
            "diagnostic_catalogue": {
                "clean": lint.is_clean(),
                "checked": lint.checked,
                "errors": lint.errors().len(),
                "warnings": lint.warnings().len(),
                "finding_count": lint.findings.len(),
                "findings_returned": lint.findings.iter().take(max_items).collect::<Vec<_>>(),
                "omitted_findings": lint.findings.len().saturating_sub(max_items),
            },
            "exit_code_audit": {
                "clean": exit_audit.is_clean(),
                "retry_decision_recoverable_from_code_alone": exit_audit.retry_decision_recoverable_from_the_code_alone,
                "divergence_count": exit_audit.divergences.len(),
                "divergences_returned": exit_audit.divergences.iter().take(max_items).collect::<Vec<_>>(),
                "omitted_divergences": exit_audit.divergences.len().saturating_sub(max_items),
            },
            "limitations": [
                "the full Python SDK surface, generated domain clients, gRPC client, and GitHub Actions remain outside this Rust check; typescript/ and python/prism_sdk provide bounded API and authoring clients, but are not executed by this Rust check",
                "cookbook verification resolves names and tests textually; it does not execute every recipe",
                "developer contracts describe declared blast radius; they do not watch files or run a live debugger",
            ],
        });
        if include_details {
            result["details"] = json!({
                "devplat": devplat,
                "cookbook_verification": verification,
                "developer_contract": contract,
                "diagnostic_findings": lint.findings,
                "exit_code_divergences": exit_audit.divergences,
            });
        }

        Ok(result)
    }

    /// Build the complete deterministic workflow catalogue, including a per-group domain contract
    /// for scope, evidence retention, review gates, and completion posture.
    ///
    /// This is intentionally a planning operation, not a semantic router or permission grant.
    /// Domain contracts are structural handoff evidence; they do not infer domain truth or
    /// readiness and do not dispatch any tool.
    fn domain_workflow_catalogue(&self, arguments: &Value) -> Result<Value, String> {
        if !arguments
            .as_object()
            .is_some_and(|object| object.is_empty())
        {
            return Err("domain_workflow_catalogue accepts an empty arguments object".into());
        }
        build_domain_workflow_catalogue(
            &workspace_capabilities(),
            &Value::Array(tool_definitions()),
        )
        .map_err(|error| format!("domain workflow catalogue refused: {error}"))
    }

    /// Build an execution-disabled, schema-aware starting mission for one capability group.
    ///
    /// Kernel scaffolding chooses tools; this transport layer adds the authoritative live
    /// `tools/list` preflight. Missing required arguments therefore remain a structured blocked
    /// handoff rather than being turned into a transport-level success or an opaque failure.
    fn domain_workflow_scaffold(&self, arguments: &Value) -> Result<Value, String> {
        let mut output = scaffold_domain_workflow(
            &workspace_capabilities(),
            &Value::Array(tool_definitions()),
            arguments,
        )
        .map_err(|error| format!("domain workflow scaffold refused: {error}"))?;
        let mission = output
            .get("mission")
            .cloned()
            .ok_or_else(|| "domain workflow scaffold omitted mission".to_string())?;
        let preflight_report = match self.preflight_agent_mission(&mission) {
            Ok(report) => report,
            Err(error) => json!({
                "ok": false,
                "workflow": "agent_mission",
                "preflight": true,
                "dispatch": "not_started",
                "schema_valid": false,
                "error": error,
                "guarantees": [
                    "the scaffold remains execution-disabled",
                    "authoritative schema refusal is retained for caller correction"
                ],
                "readiness_claimed": false
            }),
        };
        let preflight_ok = preflight_report.get("ok") == Some(&Value::Bool(true));
        output["preflight_status"] = json!(if preflight_ok { "ready" } else { "blocked" });
        output["preflight_report"] = preflight_report.clone();
        output["instantiation"]["preflight_report"] = preflight_report;
        output["next_actions"] = if preflight_ok {
            json!([
                "review the selected and omitted tools for domain-specific sufficiency",
                "obtain any required operations gate acceptance",
                "execute only through an explicit allow-list and reconcile the retained report"
            ])
        } else {
            json!([
                "fill every reported required argument field from the authoritative tool schema",
                "rerun the scaffold or mission preflight after correcting arguments",
                "obtain any required operations gate acceptance before execution"
            ])
        };
        Ok(output)
    }

    /// Instantiate one explicitly selected, group-scoped workflow into a validated mission and
    /// a step-by-step evidence plan.
    ///
    /// The kernel validates mission invariants here; the server then adds the authoritative MCP
    /// schema preflight report. Neither operation dispatches a selected tool, and unavailable
    /// tools or out-of-scope policy entries fail before preflight.
    fn domain_workflow_instantiate(&self, arguments: &Value) -> Result<Value, String> {
        let mut output = instantiate_domain_workflow(
            &workspace_capabilities(),
            &Value::Array(tool_definitions()),
            arguments,
        )
        .map_err(|error| format!("domain workflow instantiation refused: {error}"))?;
        let mission = output
            .get("mission")
            .cloned()
            .ok_or_else(|| "domain workflow instantiation omitted mission".to_string())?;
        let preflight_report = self
            .preflight_agent_mission(&mission)
            .map_err(|error| format!("domain workflow mission preflight refused: {error}"))?;
        output["preflight_report"] = preflight_report;
        Ok(output)
    }

    /// Plan multiple group-scoped workflows while retaining independent authoritative preflight
    /// outcomes for each item. This is a composition boundary only; it never dispatches a group
    /// tool or turns a complete portfolio into execution authorization.
    fn domain_workflow_portfolio(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments)
            .map_err(|error| format!("cannot encode domain workflow portfolio input: {error}"))?;
        if encoded.len() > bioprism_devplat::MAX_DOMAIN_WORKFLOW_BYTES {
            return Err(format!(
                "domain workflow portfolio input exceeds the {}-byte safety bound",
                bioprism_devplat::MAX_DOMAIN_WORKFLOW_BYTES
            ));
        }
        let mut output = build_domain_workflow_portfolio(
            &workspace_capabilities(),
            &Value::Array(tool_definitions()),
            arguments,
        )
        .map_err(|error| format!("domain workflow portfolio refused: {error}"))?;
        let mut preflight_blocked_count = 0usize;
        if let Some(items) = output.get_mut("items").and_then(Value::as_array_mut) {
            for item in items.iter_mut() {
                if item.get("status").and_then(Value::as_str) != Some("instantiated") {
                    continue;
                }
                let mission = item
                    .pointer("/instantiation/mission")
                    .cloned()
                    .ok_or_else(|| "portfolio item omitted instantiated mission".to_string())?;
                let preflight = match self.preflight_agent_mission(&mission) {
                    Ok(value) => value,
                    Err(error) => json!({
                        "ok": false,
                        "workflow": "agent_mission",
                        "preflight": true,
                        "dispatch": "not_started",
                        "schema_valid": false,
                        "error": error,
                        "fail_closed": true,
                        "readiness_claimed": false
                    }),
                };
                let preflight_ok = preflight.get("ok") == Some(&Value::Bool(true));
                let observed_plan_digest = preflight
                    .pointer("/plan/digest")
                    .cloned()
                    .unwrap_or(Value::Null);
                let preflight_status = if preflight_ok { "matched" } else { "blocked" };
                item["mission_preflight"] = json!({
                    "status": preflight_status,
                    "matched": preflight_ok,
                    "ok": preflight_ok,
                    "observed_plan_digest": observed_plan_digest,
                    "dispatch": "not_started"
                });
                item["instantiation"]["preflight_report"] = preflight.clone();
                if !preflight_ok {
                    preflight_blocked_count = preflight_blocked_count.saturating_add(1);
                    item["status"] = json!("blocked_by_mission_preflight");
                    item["issues"] = json!([{
                        "code": "mission_preflight_blocked",
                        "message": "authoritative mission schema preflight blocked this portfolio item",
                        "preflight": preflight
                    }]);
                }
            }
        }
        let kernel_valid = output
            .get("valid")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let valid = kernel_valid && preflight_blocked_count == 0;
        output["valid"] = json!(valid);
        output["portfolio_ready"] = json!(valid);
        output["summary"]["preflight_blocked_count"] = json!(preflight_blocked_count);
        output["summary"]["preflight_status"] = json!(if preflight_blocked_count == 0 {
            "matched"
        } else {
            "blocked"
        });
        output["preflight"] = json!({
            "required": true,
            "status": if preflight_blocked_count == 0 { "matched" } else { "blocked" },
            "matched": preflight_blocked_count == 0,
            "blocked_count": preflight_blocked_count,
            "dispatch": "not_started"
        });
        if preflight_blocked_count > 0 {
            let allow_partial = output
                .pointer("/policy/allow_partial")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            output["portfolio_status"] = json!(if allow_partial { "partial" } else { "blocked" });
        }
        output["dispatch"] = json!("not_started");
        output["execution"] = json!("not_started");
        if let Some(object) = output.as_object_mut() {
            object.remove("portfolio_digest");
        }
        let digest = bioprism_ids::ContentHash::of_value(&output)
            .map_err(|error| format!("cannot digest domain workflow portfolio: {error}"))?;
        output["portfolio_digest"] = json!(digest.to_string());
        Ok(output)
    }

    /// Verify a retained multi-domain portfolio, replay aligned requests when supplied, and
    /// preflight every structurally successful item against the authoritative live tool schemas.
    /// This is an audit projection only: no selected tool is dispatched, retried, resumed, or
    /// promoted to execution readiness.
    fn domain_workflow_portfolio_verify(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments).map_err(|error| {
            format!("cannot encode domain workflow portfolio verification input: {error}")
        })?;
        if encoded.len() > bioprism_devplat::MAX_DOMAIN_WORKFLOW_BYTES {
            return Err(format!(
                "domain workflow portfolio verification input exceeds the {}-byte safety bound",
                bioprism_devplat::MAX_DOMAIN_WORKFLOW_BYTES
            ));
        }
        let mut output = verify_domain_workflow_portfolio(
            &workspace_capabilities(),
            &Value::Array(tool_definitions()),
            arguments,
        )
        .map_err(|error| format!("domain workflow portfolio verification refused: {error}"))?;
        let mut preflight_attempted_count = 0usize;
        let mut preflight_blocked_count = 0usize;
        if let Some(items) = output.get_mut("items").and_then(Value::as_array_mut) {
            for item in items.iter_mut() {
                let structurally_verified = matches!(
                    item.get("status").and_then(Value::as_str),
                    Some("verified") | Some("verified_without_replay")
                );
                if !structurally_verified {
                    continue;
                }
                let mission = item
                    .pointer("/instantiation/mission")
                    .cloned()
                    .ok_or_else(|| {
                        "portfolio verification item omitted verified mission".to_string()
                    })?;
                preflight_attempted_count = preflight_attempted_count.saturating_add(1);
                let preflight = match self.preflight_agent_mission(&mission) {
                    Ok(value) => value,
                    Err(error) => json!({
                        "ok": false,
                        "workflow": "agent_mission",
                        "preflight": true,
                        "dispatch": "not_started",
                        "schema_valid": false,
                        "error": error,
                        "fail_closed": true,
                        "readiness_claimed": false
                    }),
                };
                let preflight_ok = preflight.get("ok") == Some(&Value::Bool(true));
                let expected_plan_digest = item
                    .pointer("/instantiation/preflight_report/plan/digest")
                    .cloned()
                    .unwrap_or(Value::Null);
                let observed_plan_digest = preflight
                    .pointer("/plan/digest")
                    .cloned()
                    .unwrap_or(Value::Null);
                let mut item_mismatches = item
                    .get("mismatches")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                let preflight_status = if !preflight_ok {
                    item_mismatches.push(json!({
                        "code": "mission_preflight_blocked",
                        "expected": expected_plan_digest,
                        "observed": observed_plan_digest,
                        "message": "authoritative mission schema preflight blocked this portfolio verification item"
                    }));
                    preflight_blocked_count = preflight_blocked_count.saturating_add(1);
                    item["status"] = json!("blocked_by_mission_preflight");
                    "blocked"
                } else if expected_plan_digest.is_null() {
                    item_mismatches.push(json!({
                        "code": "retained_preflight_missing",
                        "message": "the retained instantiation has no authoritative preflight plan digest",
                        "observed": observed_plan_digest
                    }));
                    preflight_blocked_count = preflight_blocked_count.saturating_add(1);
                    item["status"] = json!("blocked_by_mission_preflight");
                    "retained_projection_missing"
                } else if expected_plan_digest != observed_plan_digest {
                    item_mismatches.push(json!({
                        "code": "mission_plan_digest_mismatch",
                        "expected": expected_plan_digest,
                        "observed": observed_plan_digest
                    }));
                    preflight_blocked_count = preflight_blocked_count.saturating_add(1);
                    item["status"] = json!("blocked_by_mission_preflight");
                    "mismatched"
                } else {
                    "matched"
                };
                item["mission_preflight"] = json!({
                    "requested": true,
                    "status": preflight_status,
                    "matched": preflight_status == "matched",
                    "ok": preflight_ok,
                    "expected_plan_digest": expected_plan_digest,
                    "observed_plan_digest": observed_plan_digest,
                    "dispatch": "not_started"
                });
                item["verification"]["mission_preflight"] = item["mission_preflight"].clone();
                item["verification"]["preflight_report"] = preflight.clone();
                item["instantiation"]["preflight_report"] = preflight;
                item["mismatches"] = Value::Array(item_mismatches);
            }
        }
        let kernel_valid = output
            .get("valid")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let valid = kernel_valid && preflight_blocked_count == 0;
        output["valid"] = json!(valid);
        output["portfolio_ready"] = json!(valid);
        let kernel_blocked_count = output
            .pointer("/summary/blocked_count")
            .and_then(Value::as_u64)
            .unwrap_or(0) as usize;
        output["summary"]["blocked_count"] =
            json!(kernel_blocked_count.saturating_add(preflight_blocked_count));
        output["summary"]["preflight_attempted_count"] = json!(preflight_attempted_count);
        output["summary"]["preflight_blocked_count"] = json!(preflight_blocked_count);
        output["summary"]["preflight_status"] = json!(if preflight_blocked_count > 0 {
            "blocked"
        } else if preflight_attempted_count > 0 {
            "matched"
        } else {
            "deferred"
        });
        output["preflight"] = json!({
            "required": true,
            "status": if preflight_blocked_count > 0 {
                "blocked"
            } else if preflight_attempted_count > 0 {
                "matched"
            } else {
                "deferred"
            },
            "matched": preflight_blocked_count == 0 && preflight_attempted_count > 0,
            "attempted_count": preflight_attempted_count,
            "blocked_count": preflight_blocked_count,
            "dispatch": "not_started"
        });
        let mut mismatches = output
            .get("mismatches")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        if preflight_blocked_count > 0 {
            mismatches.push(json!({
                "code": "portfolio_mission_preflight_blocked",
                "blocked_count": preflight_blocked_count
            }));
        }
        output["mismatches"] = Value::Array(mismatches);
        let status = if valid {
            output
                .get("verification_status")
                .cloned()
                .unwrap_or_else(|| json!("verified"))
        } else if preflight_blocked_count > 0 {
            json!(if output
                .pointer("/policy/allow_partial")
                .and_then(Value::as_bool)
                .unwrap_or(false)
            {
                "partial"
            } else {
                "blocked_by_mission_preflight"
            })
        } else {
            output
                .get("verification_status")
                .cloned()
                .unwrap_or_else(|| json!("mismatch"))
        };
        output["verification_status"] = status;
        output["dispatch"] = json!("not_started");
        output["execution"] = json!("not_started");
        if let Some(object) = output.as_object_mut() {
            object.remove("portfolio_verify_digest");
        }
        let digest = bioprism_ids::ContentHash::of_value(&output).map_err(|error| {
            format!("cannot digest domain workflow portfolio verification: {error}")
        })?;
        output["portfolio_verify_digest"] = json!(digest.to_string());
        Ok(output)
    }

    /// Verify a retained domain workflow against the live catalogue and authoritative mission
    /// preflight without dispatching any selected tool.
    fn domain_workflow_verify(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments).map_err(|error| {
            format!("cannot encode domain workflow verification input: {error}")
        })?;
        if encoded.len() > bioprism_devplat::MAX_DOMAIN_WORKFLOW_BYTES {
            return Err(format!(
                "domain workflow verification input exceeds the {}-byte safety bound",
                bioprism_devplat::MAX_DOMAIN_WORKFLOW_BYTES
            ));
        }
        let mut output = bioprism_devplat::verify_domain_workflow(
            &workspace_capabilities(),
            &Value::Array(tool_definitions()),
            arguments,
        )
        .map_err(|error| format!("domain workflow verification refused: {error}"))?;
        let instantiation = arguments
            .get("instantiation")
            .ok_or("domain workflow verification requires instantiation")?;
        let mission = instantiation
            .get("mission")
            .ok_or("domain workflow verification instantiation omitted mission")?;
        let preflight = match self.preflight_agent_mission(mission) {
            Ok(value) => value,
            Err(error) => json!({
                "ok": false,
                "workflow": "agent_mission",
                "preflight": true,
                "dispatch": "not_started",
                "schema_valid": false,
                "error": error,
                "fail_closed": true,
            }),
        };
        let preflight_ok = preflight.get("ok") == Some(&Value::Bool(true));
        let expected_plan_digest = instantiation
            .pointer("/preflight_report/plan/digest")
            .cloned()
            .unwrap_or(Value::Null);
        let observed_plan_digest = preflight
            .pointer("/plan/digest")
            .cloned()
            .unwrap_or(Value::Null);
        let mut mismatches = output
            .get("mismatches")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let preflight_status = if !preflight_ok {
            mismatches.push(json!({
                "code": "mission_preflight_blocked",
                "expected": expected_plan_digest,
                "observed": observed_plan_digest,
            }));
            "blocked"
        } else if expected_plan_digest.is_null() {
            mismatches.push(json!({
                "code": "retained_preflight_missing",
                "message": "the retained instantiation has no authoritative preflight plan digest",
                "observed": observed_plan_digest,
            }));
            "retained_projection_missing"
        } else if expected_plan_digest != observed_plan_digest {
            mismatches.push(json!({
                "code": "mission_plan_digest_mismatch",
                "expected": expected_plan_digest,
                "observed": observed_plan_digest,
            }));
            "mismatched"
        } else {
            "matched"
        };
        output["mission_preflight"] = json!({
            "requested": true,
            "status": preflight_status,
            "matched": preflight_status == "matched",
            "ok": preflight_ok,
            "expected_plan_digest": expected_plan_digest,
            "observed_plan_digest": observed_plan_digest,
            "dispatch": "not_started",
        });
        output["preflight_report"] = preflight;
        output["mismatches"] = Value::Array(mismatches.clone());
        let valid = mismatches.is_empty();
        let replay_status = output
            .pointer("/replay/status")
            .and_then(Value::as_str)
            .unwrap_or("not_requested")
            .to_owned();
        let replay_requested = output
            .pointer("/replay/requested")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        output["valid"] = json!(valid);
        output["verification_status"] = json!(if valid {
            if replay_requested {
                "verified"
            } else {
                "verified_without_replay"
            }
        } else if replay_status == "blocked" {
            "blocked_by_replay"
        } else if preflight_status == "blocked" || preflight_status == "retained_projection_missing"
        {
            "blocked_by_mission_preflight"
        } else {
            "mismatch"
        });
        output["execution"] = json!("not_started");
        output["dispatch"] = json!("not_started");
        Ok(output)
    }

    /// Reconcile a retained mission report or evidence bundle against an instantiated workflow.
    ///
    /// This is an audit projection only. It checks plan and tool identity, result counters,
    /// trace lifecycle, output retention, refusal/omission posture, and completion readiness;
    /// it never retries or dispatches a domain tool.
    fn domain_workflow_reconcile(&self, arguments: &Value) -> Result<Value, String> {
        reconcile_domain_workflow(arguments)
            .map_err(|error| format!("domain workflow reconciliation refused: {error}"))
    }

    /// Import a previously produced reconciliation report into the bounded process-local audit
    /// registry. The report digest is recomputed before it becomes queryable.
    fn domain_workflow_reconciliation_import(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments).map_err(|error| {
            format!("cannot encode domain workflow reconciliation import input: {error}")
        })?;
        if encoded.len() > bioprism_devplat::MAX_DOMAIN_WORKFLOW_RECONCILIATION_BYTES {
            return Err(format!(
                "domain workflow reconciliation import input exceeds the {}-byte bound",
                bioprism_devplat::MAX_DOMAIN_WORKFLOW_RECONCILIATION_BYTES
            ));
        }
        let record = arguments.get("record").ok_or("record is required")?;
        self.workflow_reconciliation_registry
            .lock()
            .map_err(|_| "workflow reconciliation registry lock is poisoned".to_string())?
            .import(record)
            .map_err(|error| format!("domain workflow reconciliation import refused: {error}"))
    }

    /// Query digest-ordered reconciliation rows without executing or re-evaluating anything.
    fn domain_workflow_reconciliation_query(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments).map_err(|error| {
            format!("cannot encode domain workflow reconciliation query input: {error}")
        })?;
        if encoded.len() > 1_000_000 {
            return Err(
                "domain workflow reconciliation query input exceeds the 1000000-byte bound".into(),
            );
        }
        let optional_string = |name: &str| -> Result<Option<&str>, String> {
            arguments
                .get(name)
                .map(|value| {
                    value
                        .as_str()
                        .ok_or_else(|| format!("{name} must be a string"))
                })
                .transpose()
        };
        let mission_id = optional_string("mission_id")?;
        let workflow_id = optional_string("workflow_id")?;
        let mission_plan_digest = optional_string("mission_plan_digest")?;
        let completion_status = optional_string("completion_status")?;
        let decision_readiness_state = optional_string("decision_readiness_state")?;
        let after = optional_string("after")?;
        let max_items = arguments
            .get("max_items")
            .map(|value| {
                value
                    .as_u64()
                    .ok_or_else(|| "max_items must be an integer".to_string())
                    .and_then(|number| {
                        usize::try_from(number).map_err(|_| "max_items is too large".to_string())
                    })
            })
            .transpose()?
            .unwrap_or(100);
        if !(1..=bioprism_devplat::MAX_DOMAIN_WORKFLOW_RECONCILIATION_QUERY_ITEMS)
            .contains(&max_items)
        {
            return Err(format!(
                "max_items must be between 1 and {}",
                bioprism_devplat::MAX_DOMAIN_WORKFLOW_RECONCILIATION_QUERY_ITEMS
            ));
        }
        let include_records = arguments
            .get("include_records")
            .map(|value| value.as_bool().ok_or("include_records must be a boolean"))
            .transpose()?
            .unwrap_or(false);
        let decision_readiness_gate_satisfied = arguments
            .get("decision_readiness_gate_satisfied")
            .map(|value| {
                value
                    .as_bool()
                    .ok_or("decision_readiness_gate_satisfied must be a boolean")
            })
            .transpose()?;
        self.workflow_reconciliation_registry
            .lock()
            .map_err(|_| "workflow reconciliation registry lock is poisoned".to_string())?
            .query(
                mission_id,
                workflow_id,
                mission_plan_digest,
                completion_status,
                decision_readiness_state,
                decision_readiness_gate_satisfied,
                after,
                max_items,
                include_records,
            )
            .map_err(|error| format!("domain workflow reconciliation query refused: {error}"))
    }

    /// Fetch one imported reconciliation report by its content hash.
    fn domain_workflow_reconciliation_get(&self, arguments: &Value) -> Result<Value, String> {
        let digest = arguments
            .get("reconciliation_digest")
            .and_then(Value::as_str)
            .ok_or("reconciliation_digest is required and must be a content hash")?;
        bioprism_ids::ContentHash::parse(digest.to_string())
            .map_err(|error| format!("reconciliation_digest is invalid: {error}"))?;
        let record = self
            .workflow_reconciliation_registry
            .lock()
            .map_err(|_| "workflow reconciliation registry lock is poisoned".to_string())?
            .get(digest)
            .ok_or_else(|| format!("reconciliation {digest:?} is not present in the registry"))?;
        Ok(json!({
            "ok": true,
            "schema": "bioprism-mcp/domain-workflow-reconciliation-record/0.1",
            "workflow": "domain_workflow_reconciliation_get",
            "reconciliation_digest": digest,
            "record": record,
            "execution": "not_started",
            "guarantees": [
                "the returned report passed the shared reconciliation digest check before import",
                "lookup does not execute, retry, resume, or mutate a mission"
            ],
            "limitations": [
                "the process-local registry is bounded and is not a distributed audit store",
                "report presence does not establish scientific validity, clinical safety, or release approval"
            ]
        }))
    }

    /// Search the complete workspace capability catalogue and optionally attach authoritative MCP
    /// schemas for the matched tools.
    ///
    /// This is intentionally a discovery operation, not a semantic router or permission grant.
    /// Scores only reflect explicit label matches; callers still need to inspect the returned
    /// domain, evidence, policy, and tool contracts before constructing a mission.
    fn capability_discover(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments)
            .map_err(|error| format!("cannot encode capability discovery input: {error}"))?;
        if encoded.len() > 20_000_000 {
            return Err("capability discovery input exceeds the 20000000-byte safety bound".into());
        }
        let query: CapabilityQuery = serde_json::from_value(arguments.clone())
            .map_err(|error| format!("invalid capability discovery input: {error}"))?;
        let catalogue = CapabilityCatalogue::from_value(&workspace_capabilities())
            .map_err(|error| format!("capability catalogue refused: {error}"))?;
        let search = catalogue
            .search(&query)
            .map_err(|error| format!("capability discovery refused: {error}"))?;
        let mut output = serde_json::to_value(search)
            .map_err(|error| format!("cannot encode capability discovery result: {error}"))?;
        let mut schema_missing = Vec::new();
        let mut schema_returned = 0usize;
        if query.include_tools {
            let definitions = tool_definitions();
            let definitions = definitions
                .into_iter()
                .filter_map(|definition| {
                    let name = definition
                        .get("name")
                        .and_then(Value::as_str)
                        .map(str::to_string);
                    name.map(|name| (name, definition))
                })
                .collect::<BTreeMap<_, _>>();
            if let Some(matches) = output.get_mut("matches").and_then(Value::as_array_mut) {
                for matched in matches {
                    let tool_names = matched
                        .get("matched_tools")
                        .and_then(Value::as_array)
                        .cloned()
                        .unwrap_or_default();
                    let mut schemas = Vec::new();
                    for tool_name in tool_names.iter().filter_map(Value::as_str) {
                        if let Some(definition) = definitions.get(tool_name) {
                            schemas.push(definition.clone());
                        } else {
                            schema_missing.push(tool_name.to_string());
                        }
                    }
                    schema_returned += schemas.len();
                    matched["tool_schemas"] = Value::Array(schemas);
                }
            }
        }
        output["ok"] = json!(true);
        output["workflow"] = json!("capability_discover");
        output["capability_schema_version"] = json!(CAPABILITY_SCHEMA_VERSION);
        output["schema_attachment"] = json!({
            "requested": query.include_tools,
            "returned": schema_returned,
            "missing": schema_missing,
            "authoritative_source": "tools/list definition set"
        });
        let output_bytes = serde_json::to_vec(&output)
            .map_err(|error| format!("cannot measure capability discovery result: {error}"))?;
        if output_bytes.len() > 20_000_000 {
            return Err(
                "capability discovery result exceeds the 20000000-byte safety bound".into(),
            );
        }
        Ok(output)
    }

    /// Search the explicit evaluator candidate catalogue across every workspace domain.
    ///
    /// The returned rows are discovery evidence only. They help a caller choose an
    /// `adapter_id` for a mission claim, but they do not execute an evaluator, inspect a step
    /// result, grant permission, or establish the truth of the claim.
    fn mission_evaluator_discover(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments)
            .map_err(|error| format!("cannot encode mission evaluator discovery input: {error}"))?;
        if encoded.len() > 20_000_000 {
            return Err(
                "mission evaluator discovery input exceeds the 20000000-byte safety bound".into(),
            );
        }
        let query: MissionEvaluatorQuery = serde_json::from_value(arguments.clone())
            .map_err(|error| format!("invalid mission evaluator discovery input: {error}"))?;
        let catalogue = MissionEvaluatorCatalogue::standard();
        let search = catalogue
            .search(&query)
            .map_err(|error| format!("mission evaluator discovery refused: {error}"))?;
        let capability_catalogue = CapabilityCatalogue::from_value(&workspace_capabilities())
            .map_err(|error| format!("capability catalogue refused: {error}"))?;
        let evaluator_groups = catalogue
            .adapters()
            .iter()
            .map(|adapter| adapter.group_id.clone())
            .collect::<BTreeSet<_>>();
        let capability_groups = capability_catalogue
            .groups()
            .iter()
            .map(|group| group.id.clone())
            .collect::<BTreeSet<_>>();
        let uncovered_groups = capability_groups
            .difference(&evaluator_groups)
            .cloned()
            .collect::<Vec<_>>();
        let unbound_groups = evaluator_groups
            .difference(&capability_groups)
            .cloned()
            .collect::<Vec<_>>();
        let coverage_complete = uncovered_groups.is_empty() && unbound_groups.is_empty();
        let mut output = serde_json::to_value(search).map_err(|error| {
            format!("cannot encode mission evaluator discovery result: {error}")
        })?;
        output["ok"] = json!(true);
        output["workflow"] = json!("mission_evaluator_discover");
        output["mission_evaluator_schema_version"] = json!(MISSION_EVALUATOR_SCHEMA_VERSION);
        output["selection_posture"] = json!("candidate_only");
        output["coverage"] = json!({
            "capability_group_count": capability_groups.len(),
            "evaluator_group_count": evaluator_groups.len(),
            "uncovered_groups": uncovered_groups,
            "unbound_groups": unbound_groups,
            "complete": coverage_complete,
            "posture": "catalogue coverage evidence only; no evaluator was executed",
        });
        output["guarantees"] = json!([
            "every returned adapter is an explicit catalogue row with a stable content digest",
            "ranking is deterministic and uses labels only",
            "candidate tools are suggestions and were not executed",
            "a caller must bind an adapter explicitly to a mission claim and step output pointer",
        ]);
        output["limitations"] = json!([
            "the catalogue does not execute adapters or validate domain semantics",
            "candidate_tools do not prove that a concrete result contains the suggested fields",
            "adapter discovery does not make a claim reviewed, calibrated, causal, clinical, or release-ready",
        ]);
        let output_bytes = serde_json::to_vec(&output).map_err(|error| {
            format!("cannot measure mission evaluator discovery result: {error}")
        })?;
        if output_bytes.len() > 20_000_000 {
            return Err(
                "mission evaluator discovery result exceeds the 20000000-byte safety bound".into(),
            );
        }
        Ok(output)
    }

    /// Review caller-selected evaluator candidates and produce a non-executing claim-binding
    /// scaffold. The normal agent_mission validator remains the authority for final step and
    /// claim validation.
    fn mission_evaluator_review(&self, arguments: &Value) -> Result<Value, String> {
        let encoded = serde_json::to_vec(arguments)
            .map_err(|error| format!("cannot encode mission evaluator review input: {error}"))?;
        if encoded.len() > 20_000_000 {
            return Err(
                "mission evaluator review input exceeds the 20000000-byte safety bound".into(),
            );
        }
        let request: MissionEvaluatorReviewRequest = serde_json::from_value(arguments.clone())
            .map_err(|error| format!("invalid mission evaluator review input: {error}"))?;
        let catalogue = MissionEvaluatorCatalogue::standard();
        let output = catalogue
            .review(&request)
            .map_err(|error| format!("mission evaluator review refused: {error}"))?;
        let output_bytes = serde_json::to_vec(&output)
            .map_err(|error| format!("cannot measure mission evaluator review result: {error}"))?;
        if output_bytes.len() > 20_000_000 {
            return Err(
                "mission evaluator review result exceeds the 20000000-byte safety bound".into(),
            );
        }
        Ok(output)
    }

